INSERT INTO `courses` (`id`, `action_user`, `course_industries_id`, `qualification_id`, `course_categories_id`, `course_code`, `course_name`, `course_desc`, `rto`, `thumbnail`, `checklist`, `isPublished`, `created_at`, `updated_at`) VALUES
(74, 1, 6, 1, 25, 'MSF40413', 'Certificate IV in Glass and Glazing', '<h2>Qualification Description</h2>\r\n<p>This qualification describes the skills and knowledge required to perform in a range of specialist and/or leadership roles, including sales, scheduling, design, production control and quality assurance functions, in a glass and glazing enterprise. This is a senior qualification with scope for entry from trade and non-trade backgrounds with relevant glass industry experience.</p>\r\n<p>&nbsp;</p>\r\n<p>Leadership job roles include higher tradesperson (post-trade), factory-based leading hands/supervisors or site supervisors in glass processing, glazing or architectural glass functions in residential and commercial operations. The roles could include requirements to evaluate and analyse current practices, develop new criteria and procedures for performing current practices, and provision of leadership and guidance to others in the application and planning of glass and glazing skills. The qualification has elective options in sales and estimating, production planning, scheduling, stock control and procurement.</p>\r\n<p>&nbsp;</p>\r\n<p>There are no specific licences that relate to this qualification. However, depending on the jurisdiction, licensing or regulatory requirements may apply to the use of some units in this qualification. Local regulations should be checked for details.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>This qualification may be accessed by direct entry and it is an industry expectation that it will be undertaken primarily by those who have completed the MSF30413 Certificate III in Glass and Glazing qualification or achieved equivalent industry experience.</p>\r\n<h2>Packaging Rules</h2>\r\n<p>To be awarded the MSF40413 Certificate IV in Glass and Glazing, competency must be achieved in&nbsp;eighteen (18)&nbsp;&nbsp;units of competency.</p>\r\n<ul>\r\n<li>four (4)&nbsp; core units of competency</li>\r\n<li>fourteen (14)&nbsp; elective units of competency.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Note: Units marked with an asterisk have one or more prerequisites and must be considered in the total number of units. Please refer to individual units for details.</p>\r\n<p>&nbsp;</p>\r\n<p>CORE UNITS&nbsp;&nbsp;</p>\r\n<p>Complete all&nbsp;four (4)&nbsp; units from this list.</p>\r\n<p>&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"250\">\r\n<p>Unit code&nbsp;</p>\r\n</td>\r\n<td width=\"815\">\r\n<p>Unit title&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"250\">\r\n<p>BSBMGT401</p>\r\n</td>\r\n<td width=\"815\">\r\n<p>Show leadership in the workplace</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"250\">\r\n<p>BSBWHS401</p>\r\n</td>\r\n<td width=\"815\">\r\n<p>Implement and monitor WHS policies, procedures and programs to meet legislative requirements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"250\">\r\n<p>MSMENV472</p>\r\n</td>\r\n<td width=\"815\">\r\n<p>Implement and monitor environmentally sustainable work practices</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"250\">\r\n<p>MSFGG4001</p>\r\n</td>\r\n<td width=\"815\">\r\n<p>Apply standards and codes of practice for the glass industry</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>ELECTIVE UNITS&nbsp;&nbsp;</p>\r\n<p>Select a minimum of&nbsp;ten (10)&nbsp; units from Groups A, B, C, D and E as specified below.</p>\r\n<p>&nbsp;</p>\r\n<p>Group A &ndash; Sales and Estimating&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"262\">\r\n<p>Unit code&nbsp;</p>\r\n</td>\r\n<td width=\"746\">\r\n<p>Unit title&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"262\">\r\n<p>BSBCUS402</p>\r\n</td>\r\n<td width=\"746\">\r\n<p>Address customer needs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"262\">\r\n<p>BSBCUS501</p>\r\n</td>\r\n<td width=\"746\">\r\n<p>Manage quality customer service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"262\">\r\n<p>BSBPMG409</p>\r\n</td>\r\n<td width=\"746\">\r\n<p>Apply project scope management techniques</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"262\">\r\n<p>BSBPRO401</p>\r\n</td>\r\n<td width=\"746\">\r\n<p>Develop product knowledge</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"262\">\r\n<p>BSBSLS408</p>\r\n</td>\r\n<td width=\"746\">\r\n<p>Present, secure and support sales solutions</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"262\">\r\n<p>CPCCBC4012B</p>\r\n</td>\r\n<td width=\"746\">\r\n<p>Read and interpret plans and specifications</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"262\">\r\n<p>MSFFT4012</p>\r\n</td>\r\n<td width=\"746\">\r\n<p>Prepare a tender submission</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"262\">\r\n<p>MSFGG4002</p>\r\n</td>\r\n<td width=\"746\">\r\n<p>Use glass industry data systems</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"262\">\r\n<p>MSS402031</p>\r\n</td>\r\n<td width=\"746\">\r\n<p>Interpret product costs in terms of customer requirements</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Group B &ndash; Production and Scheduling&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"247\">\r\n<p>Unit code&nbsp;</p>\r\n</td>\r\n<td width=\"761\">\r\n<p>Unit title&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"247\">\r\n<p>CPCCBC4005A</p>\r\n</td>\r\n<td width=\"761\">\r\n<p>Produce labour and material schedules for ordering</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"247\">\r\n<p>MSAPMSUP201A</p>\r\n</td>\r\n<td width=\"761\">\r\n<p>Receive or despatch goods</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"247\">\r\n<p>MSFFT4007</p>\r\n</td>\r\n<td width=\"761\">\r\n<p>Sample, inspect and test products to specifications</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"247\">\r\n<p>MSFFT4010</p>\r\n</td>\r\n<td width=\"761\">\r\n<p>Identify and calculate production costs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"247\">\r\n<p>MSFFT4011</p>\r\n</td>\r\n<td width=\"761\">\r\n<p>Purchase materials and consumables</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"247\">\r\n<p>MSFGG4003</p>\r\n</td>\r\n<td width=\"761\">\r\n<p>Manage glass industry production scheduling</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"247\">\r\n<p>TLIA4028</p>\r\n</td>\r\n<td width=\"761\">\r\n<p>Assess and monitor optimum stock levels</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"247\">\r\n<p>TLIA4032</p>\r\n</td>\r\n<td width=\"761\">\r\n<p>Organise transport of freight or goods</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Group C - Technical&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"257\">\r\n<p>Unit code&nbsp;</p>\r\n</td>\r\n<td width=\"771\">\r\n<p>Unit title&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"257\">\r\n<p>MEM16006A</p>\r\n</td>\r\n<td width=\"771\">\r\n<p>Organise and communicate information</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"257\">\r\n<p>MEM16008A</p>\r\n</td>\r\n<td width=\"771\">\r\n<p>Interact with computing technology</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"257\">\r\n<p>MEM30031A</p>\r\n</td>\r\n<td width=\"771\">\r\n<p>Operate computer-aided design (CAD) system to produce basic design elements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"257\">\r\n<p>MSFDN4003</p>\r\n</td>\r\n<td width=\"771\">\r\n<p>Produce patterns and templates</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"257\">\r\n<p>MSFDN5001</p>\r\n</td>\r\n<td width=\"771\">\r\n<p>Generate and transfer complex computer-aided drawings and specifications</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"257\">\r\n<p>MSFFM3009</p>\r\n</td>\r\n<td width=\"771\">\r\n<p>Produce manual and computer-aided production drawings</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"257\">\r\n<p>MSFGG4004</p>\r\n</td>\r\n<td width=\"771\">\r\n<p>Perform laser measurement and levelling for glass windows and doors in buildings</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"257\">\r\n<p>MSFGG4005</p>\r\n</td>\r\n<td width=\"771\">\r\n<p>Set up, configure, upgrade and troubleshoot glass and glazing plant and ancillary equipment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"257\">\r\n<p>MSFGG4006</p>\r\n</td>\r\n<td width=\"771\">\r\n<p>Operate complex glass industry control systems</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"257\">\r\n<p>MSFGG4007</p>\r\n</td>\r\n<td width=\"771\">\r\n<p>Manage glass processing plant shutdown and re-start</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Group D &ndash; Leading and Supervising&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"264\">\r\n<p>Unit code&nbsp;</p>\r\n</td>\r\n<td width=\"764\">\r\n<p>Unit title&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"264\">\r\n<p>BSBLDR403</p>\r\n</td>\r\n<td width=\"764\">\r\n<p>Lead team effectiveness</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"264\">\r\n<p>ICPSUP455</p>\r\n</td>\r\n<td width=\"764\">\r\n<p>Supervise and schedule the work of others</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"264\">\r\n<p>MSFGG4008</p>\r\n</td>\r\n<td width=\"764\">\r\n<p>Undertake planning and coordination for commercial glazing installation operations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"264\">\r\n<p>MSS403021</p>\r\n</td>\r\n<td width=\"764\">\r\n<p>Facilitate a Just in Time system</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"264\">\r\n<p>MSS404050</p>\r\n</td>\r\n<td width=\"764\">\r\n<p>Undertake process capability improvements*</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"264\">\r\n<p>MSS404052</p>\r\n</td>\r\n<td width=\"764\">\r\n<p>Apply statistics to operational processes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"264\">\r\n<p>TAEDEL404</p>\r\n</td>\r\n<td width=\"764\">\r\n<p>Mentor in the workplace</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"264\">\r\n<p>TAEDEL402</p>\r\n</td>\r\n<td width=\"764\">\r\n<p>Plan, organise and facilitate learning in the workplace</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Group E&nbsp;</p>\r\n<p>Up to&nbsp;four (4)&nbsp; relevant units can be chosen from other units not already selected from Groups A to D or units available in this Training Package, other endorsed Training Packages and accredited courses. Those units must be aligned at Certificate III level (maximum 1 unit), Certificate IV level (maximum 4 units) or Diploma level (maximum 1 unit).</p>\r\n<p>&nbsp;</p>\r\n<p>Units selected from other Training Packages and accredited courses must be relevant to the qualification outcome and not duplicate units available within this qualification.</p>', NULL, '20.jpg', 'MSF40413.pdf', 1, '2021-04-27 01:38:59', '2021-06-02 03:49:27'),
(75, 1, 11, 1, 25, 'SHB40115', 'Certificate IV in Beauty Therapy', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of individuals who work as beauty therapists to provide a range of beauty therapy treatments and services, including lash and brow treatments, nail services, make-up, massage and waxing. They communicate with clients to recommend treatments and services and sell retail skin care and cosmetic products.</p>\r\n<p>&nbsp;</p>\r\n<p>These individuals undertake work independently, with limited guidance from others, to perform routine and non-routine activities and solve non-routine problems. They apply and adapt technical skills and knowledge, and use judgment in the provision of beauty treatments and services. These individuals are responsible for their own outputs and provide limited guidance to others.</p>\r\n<p>&nbsp;</p>\r\n<p>Work is typically conducted in beauty salons and spas.</p>\r\n<p>&nbsp;</p>\r\n<p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>There are no entry requirements for this qualification.</p>\r\n<h2>Packaging Rules</h2>\r\n<p>19 units must be completed:</p>\r\n<ul>\r\n<li>13 core units</li>\r\n<li>6 elective units, consisting of:</li>\r\n</ul>\r\n<ul>\r\n<li>3 units from the list below</li>\r\n<li>3 units from the list below, elsewhere in SHB Training Package, or any other current Training Package or accredited course.</li>\r\n</ul>\r\n<p>The selection of electives must be guided by the job outcome sought, local industry requirements and the complexity of skills appropriate to the AQF level of this qualification.</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Core units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBBOS001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Apply cosmetic tanning products</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBBOS002</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Provide body massages</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBBOS003</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Provide body treatments</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBFAS001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Provide lash and brow services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBFAS002</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Provide facial treatments and skin care recommendations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBHRS001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Provide waxing services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBMUP002</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Design and apply make-up</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBNLS001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Provide manicure and pedicare services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBRES001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Research and apply beauty industry information</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBXCCS001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Conduct salon financial transactions</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBXCCS002</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Provide salon services to clients</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBXIND001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Comply with organisational requirements within a personal services environment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBXWHS001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Apply safe hygiene, health and work practices</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Elective units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBBOS004</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Provide aromatherapy massages</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBFAS003</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Provide specialised facial treatments</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBMUP001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Apply eyelash extensions</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBMUP003</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Design and apply make-up for photography</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBMUP004</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Design and apply remedial camouflage make-up</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBNLS002</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Apply gel nail enhancements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBNLS003</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Apply acrylic nail enhancements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBNLS004</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Apply nail art</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBNLS005</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Use electric file equipment for nail services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"318\">\r\n<p>SHBBNLS006</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Apply advanced nail art</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', 'Noble Training Academy', '27.jpg', 'SHB40115.pdf', 1, '2021-04-27 01:39:46', '2021-06-02 02:42:08'),
(76, 1, 11, 1, 25, 'SHB40216', 'Certificate IV in Hairdressing', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of skilled senior hairdressers who use a range of highly developed sales, consultation and technical skills and knowledge to provide a broad range of hairdressing services to clients. These senior hairdressers provide specialist services in one or more areas including haircutting, design, colouring and complex colour correction, trichology and chemical reformation. They work independently and many hairdressers at this level provide technical leadership, training and support to team members</p>\r\n<p>&nbsp;</p>\r\n<p>This qualification provides a pathway to work as a senior hairdresser in a salon environment, a freelance session stylist or a technical advisor in product companies.</p>\r\n<p>&nbsp;</p>\r\n<p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Entry to this qualification is open to individuals who have:</p>\r\n<p>1. achieved a Certificate III in Hairdressing (or equivalent);&nbsp;and&nbsp;</p>\r\n<p>2. at least one year post-qualification full time employment experience as a hairdresser in a salon environment where they have applied the skills and knowledge covered in the above (or equivalent) qualification.</p>\r\n<h2>Packaging Rules</h2>\r\n<p>11 units must be completed:</p>\r\n<ul>\r\n<li>2 core units</li>\r\n<li>9 elective units, consisting of:</li>\r\n</ul>\r\n<ul>\r\n<li>4 units from Group A</li>\r\n<li>3 units from Group A or Group B</li>\r\n<li>2 additional units from Group B, elsewhere in the SHB Training Package, or any other current Training Package or accredited course.</li>\r\n</ul>\r\n<p>The selection of electives must be guided by the job outcome sought, local industry requirements and the complexity of skills appropriate to the AQF level of this qualification.</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Core Units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHTLS001</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Provide technical leadership to hairdressing teams</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHTLS002</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Research and use hairdressing trends to advance creative work</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Elective Units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Group A &ndash; Hairdressing Technical&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHCLS006</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Solve complex colour problems</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHCLS007</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Enhance hair designs using creative colouring and lightening techniques</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHCUT006</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Create combined haircut structures</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHCUT008</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Design and perform creative haircuts</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHDES004</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Create classic long hair up-styles</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHDES005</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Select and apply hair extensions</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHDES006</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Design and style long hair creatively</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHDES007</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Apply and maintain wigs and hairpieces</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHDES008</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Make wigs and hairpieces</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHREF001</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Curl and volumise hair with chemical treatments</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHREF003</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Straighten and relax hair with protein treatments</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHREF004</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Enhance hair designs using chemical reformation techniques</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Group B &ndash; General Electives&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>BSBINN301</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Promote innovation in a team environment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>BSBMKG413</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Promote products and services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>BSBWOR502</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Lead and manage team effectiveness</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBBMUP003</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Design and apply make-up for photography</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHTLS003</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Work as a session stylist</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHTRI002</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Conduct trichological assessments</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>SHBHTRI003</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Develop and apply scalp treatment therapies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>TAEASS401B</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Plan assessment activities and processes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>TAEASS402B</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Assess competence</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>TAEDEL301A</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Provide work skill instruction</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"392\">\r\n<p>TAEDEL402A</p>\r\n</td>\r\n<td width=\"703\">\r\n<p>Plan, organise and facilitate learning in the workplace</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '28.jpg', 'SHB40216.pdf', 1, '2021-04-27 01:40:21', '2021-06-02 02:41:44'),
(77, 1, 14, 1, 25, 'SIT40416', 'Certificate IV in Hospitality', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of skilled operators who use a broad range of hospitality service, sales or operational skills combined with supervisory skills and sound knowledge of industry operations to plan, monitor and evaluate the work of team members. They operate independently or with limited guidance from others, and use discretion to solve non-routine problems.</p>\r\n<p>&nbsp;</p>\r\n<p>This qualification provides a pathway to work as a supervisor in hospitality organisations such as restaurants, hotels, motels, clubs, pubs, caf&eacute;s, and coffee shops. This qualification allows for multi-skilling and for specialisation in accommodation services, food and beverage, and gaming.</p>\r\n<p>&nbsp;</p>\r\n<p>Possible job titles include:</p>\r\n<ul>\r\n<li>bar supervisor or team leader</li>\r\n<li>concierge</li>\r\n<li>duty manager</li>\r\n<li>food and beverage supervisor or team leader</li>\r\n<li>front office supervisor or team leader</li>\r\n<li>housekeeping supervisor or team leader</li>\r\n<li>gaming supervisor or team leader</li>\r\n<li>shift manager.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>There are no entry requirements for this qualification.</p>\r\n<h2>Packaging Rules</h2>\r\n<p>21 units must be completed:</p>\r\n<ul>\r\n<li>9 core units</li>\r\n<li>12 elective units, consisting of:</li>\r\n</ul>\r\n<ul>\r\n<li>1 unit from Group A</li>\r\n<li>7 units from Group B</li>\r\n<li>4 units from Group B, elsewhere in the SIT Training Package, or any other current Training Package or accredited course.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>The selection of electives must be guided by the job outcome sought, local industry requirements and the complexity of skills appropriate to the AQF level of this qualification.</p>\r\n<p>&nbsp;</p>\r\n<table width=\"801\">\r\n<tbody>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Core units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>BSBDIV501</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Manage diversity in the workplace</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHIND004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Work effectively in hospitality service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXCCS007</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Enhance customer service experiences</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXCOM005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Manage conflict</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXFIN003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Manage finances within a budget</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXHRM001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Coach others in job skills</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXHRM003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Lead and manage people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXMGT001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Monitor work operations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXWHS003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Implement and monitor work health and safety practices</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Elective units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Group A&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHIND001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Use hygienic practices for hospitality service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXFSA001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Use hygienic practices for food safety</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Group B&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Accommodation Services &ndash; Front Office, Housekeeping and Porting&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CPPCLO2001A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Maintain hard floor surfaces</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CPPCLO2004A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Maintain carpeted floors</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CPPCLO2009A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Clean glass surfaces</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CPPCLO2010A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Clean ceiling surfaces and fittings</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CPPCLO2017A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Clean wet areas</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CPPCLO2019A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Sort and remove waste and recyclable materials</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CPPCLO2035A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Maintain cleaning storage areas</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CPPCLO3013A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Clean window coverings</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CPPCLO3016A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Wash furniture and fittings</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHACS001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Clean premises and equipment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHACS002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide housekeeping services to guests</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHACS003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare rooms for guests</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHACS004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Launder linen and guest clothes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHACS005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide porter services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHACS006</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide valet services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHACS007</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Conduct night audit</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHACS008</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide accommodation reception services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITTTSL002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Access and interpret product information</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITTTSL005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Sell tourism products and services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITTTSL006</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare quotations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITTTSL007</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Process reservations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITTTSL010</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Use a computerised reservations or operations system</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Client and Customer Service&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXCCS002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide visitor information</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXCCS004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide lost and found services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXCCS005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide club reception services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXCRI001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Respond to a customer in crisis</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Communication and Teamwork&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXCOM004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Address protocol requirements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Computer Operations and ICT Management&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>BSBITU301</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Create and use databases</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>BSBITU306</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Design and produce business documents</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>BSBITU402</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Develop and use complex spreadsheets</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>E-Business&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXEBS001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Use social media in a business</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Environmental Sustainability&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"207\">\r\n<p>BSBSUS401</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Implement and monitor environmentally sustainable work practices</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Events&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITEEVT001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Source and use information on the events industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITEEVT002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Process and monitor event registrations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITEEVT003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Coordinate on-site event registrations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITEEVT004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide event staging support</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITEEVT005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Plan in-house events or functions</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Finance&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>BSBFIA301</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Maintain financial records</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>BSBFIA401</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare financial reports</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXFIN002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Interpret financial information</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>First Aid&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>HLTAID003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide first aid</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Food and Beverage&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Clean and tidy bar areas</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide responsible service of alcohol</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Operate a bar</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare and serve non-alcoholic beverages</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare and serve espresso coffee</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB006</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide room service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB008</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Operate and monitor cellar systems</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB009</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Conduct a product tasting for alcoholic beverages</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB010</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare and serve cocktails</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB011</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide advice on beers, spirits and liqueurs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB012</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide advice on Australian wines</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB013</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide advice on imported wines</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB014</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide table service of food and beverage</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB015</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide silver service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB016</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide advice on food</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB017</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide advice on food and beverage matching</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB018</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide gueridon service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB019</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Plan and monitor espresso coffee service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Food Safety&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXFSA001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Use hygienic practices for food safety</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXFSA002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Participate in safe food handling practices</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXFSA003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Transport and store food</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Gaming&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide responsible gambling services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Attend gaming machines</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Operate a TAB outlet</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Conduct Keno games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Analyse and report on gaming machine data</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM006</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Deal Baccarat games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM007</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Conduct Big Wheel games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM008</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Deal Blackjack games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM009</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Deal Poker games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM010</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Deal Pontoon games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM011</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Conduct Rapid Roulette games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM012</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Conduct Roulette games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM013</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Conduct Sic Bo games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM015</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Attend casino gaming machines</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM016</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Deal Caribbean Stud games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM017</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Deal Casino War games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM018</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Deal Mississippi Stud games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM019</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Conduct Rapid Baccarat games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM020</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Conduct Rapid Big Wheel games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHGAM021</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Deal Three Card Poker games</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Human Resource Management&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXHRM002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Roster staff</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Inventory&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXINV002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Maintain the quality of perishable items</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXINV003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Purchase goods</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXINV004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Control stock</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Kitchen Operations&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHKOP006</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Plan catering for events or functions</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Languages other than English&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXLAN003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Conduct oral communication in a language other than English</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"207\">\r\n<p>SITXLAN004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Conduct complex oral communication in a language other than English</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXLAN005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Read and write information in a language other than English</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Marketing and Public Relations&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXMPR001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Coordinate production of brochures and marketing materials</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXMPR002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Create a promotional display or stand</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXMPR003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Plan and implement sales activities</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXMPR004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Coordinate marketing activities</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXMPR005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Participate in cooperative online marketing initiatives</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Security&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CPPSEC2012A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Monitor and control individual and crowd behaviour</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CPPSEC3018A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide for the safety of persons at risk</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Work Health and Safety&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXWHS002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Identify hazards, assess and control safety risks</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Working in Industry&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHIND001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Use hygienic practices for hospitality service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHIND002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Source and use information on the hospitality industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"207\">\r\n<p>SITTIND001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Source and use information on the tourism and travel industry</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '42.jpg', 'SIT40416.pdf', 1, '2021-04-27 01:40:55', '2021-06-02 02:49:05');
INSERT INTO `courses` (`id`, `action_user`, `course_industries_id`, `qualification_id`, `course_categories_id`, `course_code`, `course_name`, `course_desc`, `rto`, `thumbnail`, `checklist`, `isPublished`, `created_at`, `updated_at`) VALUES
(78, 1, 14, 1, 25, 'SIT40516', 'Certificate IV in Commercial Cookery', '<div>\r\n<h2>Description</h2>\r\n<p>This qualification reflects the role of commercial cooks who have a supervisory or team leading role in the kitchen. They operate independently or with limited guidance from others and use discretion to solve non-routine problems.</p>\r\n<p>&nbsp;</p>\r\n<p>This qualification is suitable for an Australian Apprenticeship pathway.</p>\r\n<p>&nbsp;</p>\r\n<p>Job roles&nbsp;</p>\r\n<p>This qualification provides a pathway to work in various kitchen settings, such as restaurants, hotels, clubs, pubs, cafes, cafeterias and coffee shops.</p>\r\n<p>&nbsp;</p>\r\n<p>Possible job titles include:</p>\r\n<ul>\r\n<li>chef</li>\r\n<li>chef de partie.</li>\r\n</ul>\r\n<h2>Pathways Information</h2>\r\n<p>Pathways into the qualification&nbsp;</p>\r\n<p>Individuals may enter SIT40413 Certificate IV in Commercial Cookery with limited or no vocational experience and without a lower level qualification. However, it is strongly recommended that individuals undertake lower level qualifications, and/or gain industry experience prior to entering the qualification.</p>\r\n<p>&nbsp;</p>\r\n<p>Pathways from the qualification&nbsp;</p>\r\n<p>After achieving SIT40413 Certificate IV in Commercial Cookery, individuals could progress to SIT50313 Diploma of Hospitality.</p>\r\n<h2>Licensing/Regulatory Information</h2>\r\n<p>No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of endorsement.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>There are no entry requirements for this qualification.</p>\r\n<h2>Employability Skills Summary</h2>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"306\">\r\n<p>Employability Skill&nbsp;</p>\r\n</td>\r\n<td width=\"790\">\r\n<p>Industry/enterprise requirements for this qualification include:&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"306\">\r\n<p>Communication</p>\r\n</td>\r\n<td width=\"790\">\r\n<p>Providing food production briefings to kitchen staff; seeking feedback from colleagues on operational and service issues; communicating changes in food production requirements during the service period; instructing kitchen staff to adjust food items to meet quality requirements and organisational standards; managing team member conflict sensitively, courteously and discreetly; empathising and negotiating acceptable solutions to team member problems.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"306\">\r\n<p>Initiative and enterprise</p>\r\n</td>\r\n<td width=\"790\">\r\n<p>Proactively consulting with colleagues about ways to improve cooking operations; providing feedback to managers to inform future planning; participating in continuous improvement by reporting success or deficiencies of recipes and menu items; suggesting ideas for new or improved products and increased profitability.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"306\">\r\n<p>Learning</p>\r\n</td>\r\n<td width=\"790\">\r\n<p>Knowing sources of new information on food trends, products, services and suppliers; being aware of opportunities to learn and participating in commercial cookery professional development activities; supporting team members to learn.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"306\">\r\n<p>Planning and organising</p>\r\n</td>\r\n<td width=\"790\">\r\n<p>Planning food production requirements and organising availability of supplies for the service period; preparing work flow schedules, food preparation lists and mise en place plans for food production according to menu and food volume requirements; monitoring and assessing operational efficiency and quality output of the kitchen during the service period; assessing the operational workflow of kitchen team members assisting then to prioritise workload to deliver a positive dining experience for customers.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"306\">\r\n<p>Problem-solving</p>\r\n</td>\r\n<td width=\"790\">\r\n<p>Identifying and assessing operational and service issues, discussing and suggesting solutions with kitchen managers; initiating short term action to resolve immediate kitchen operations or quality problems; using discretion and judgement as well as predetermined policies and procedures to guide solutions to operational problems in the kitchen.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"306\">\r\n<p>Self-management</p>\r\n</td>\r\n<td width=\"790\">\r\n<p>Understanding legal compliance issues and providing advice to team members; organising and self-directing own work priorities to coordinate cooking operations; taking responsibility for implementing predetermined policies and procedures for a range of practices including conflict management, food safety, workplace health and safety; leading and managing a team of individuals, coordinating cooking operations; proactively seeking feedback and advice on improving kitchen coordination and team leading skills.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"306\">\r\n<p>Teamwork</p>\r\n</td>\r\n<td width=\"790\">\r\n<p>Motivating and leading kitchen teams; providing instructions, support and coaching; planning work operations to take account of team member strengths; proactively sharing information, knowledge and experiences with kitchen team members.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"306\">\r\n<p>Technology</p>\r\n</td>\r\n<td width=\"790\">\r\n<p>Understanding the operating capability of, selecting and using kitchen tools and equipment, computer systems, software and information systems that assist in coordinating cooking operations and team leading activities.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<h2>Packaging Rules</h2>\r\n<p>33 units must be completed:</p>\r\n<ul>\r\n<li>27 core units</li>\r\n<li>6 elective units, consisting of:</li>\r\n</ul>\r\n<ul>\r\n<li>6 units from the list below, elsewhere in SIT12 Training Package, or any other current Training Package or accredited course</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>The selection of electives must be guided by the job outcome sought, local industry requirements and the complexity of skills appropriate to the AQF level of this qualification.</p>\r\n<p>&nbsp;</p>\r\n<p>Core units&nbsp;</p>\r\n<p>BSBDIV501A Manage diversity in the workplace</p>\r\n<p>BSBSUS301A Implement and monitor environmentally sustainable work practices</p>\r\n<p>HLTAID003 Provide first aid</p>\r\n<p>SITHCCC101 Use food preparation equipment *</p>\r\n<p>SITHCCC201 Produce dishes using basic methods of cookery *</p>\r\n<p>SITHCCC202 Produce appetisers and salads *</p>\r\n<p>SITHCCC203 Produce stocks, sauces and soups *</p>\r\n<p>SITHCCC204 Produce vegetable, fruit, egg and farinaceous dishes *</p>\r\n<p>SITHCCC301 Produce poultry dishes *</p>\r\n<p>SITHCCC302 Produce seafood dishes *</p>\r\n<p>SITHCCC303 Produce meat dishes *</p>\r\n<p>SITHCCC307 Prepare food to meet special dietary requirements *</p>\r\n<p>SITHCCC308 Produce cakes, pastries and breads *</p>\r\n<p>SITHCCC309 Work effectively as a cook *</p>\r\n<p>SITHKOP302 Plan and cost basic menus</p>\r\n<p>SITHKOP402 Develop menus for special dietary requirements</p>\r\n<p>SITHKOP403 Coordinate cooking operations *</p>\r\n<p>SITHPAT306 Produce desserts *</p>\r\n<p>SITXCOM401 Manage conflict</p>\r\n<p>SITXFIN402 Manage finances within a budget</p>\r\n<p>SITXFSA101 Use hygienic practices for food safety</p>\r\n<p>SITXFSA201 Participate in safe food handling practices</p>\r\n<p>SITXHRM301 Coach others in job skills</p>\r\n<p>SITXHRM402 Lead and manage people</p>\r\n<p>SITXINV202 Maintain the quality of perishable items *</p>\r\n<p>SITXMGT401 Monitor work operations</p>\r\n<p>SITXWHS401 Implement and monitor work health and safety practices</p>\r\n<p>*Prerequisite is SITXFSA101 Use hygienic practices for food safety</p>\r\n<p>&nbsp;</p>\r\n<p>Elective units&nbsp;</p>\r\n<p>Administration&nbsp;</p>\r\n<p>BSBRES401A Analyse and present research information</p>\r\n<p>BSBWRT401A Write complex documents</p>\r\n<p>Asian Cookery&nbsp;</p>\r\n<p>SITHASC202 Produce Asian appetisers and snacks *</p>\r\n<p>SITHASC203 Produce Asian stocks and soups *</p>\r\n<p>SITHASC204 Produce Asian sauces, dips and accompaniments *</p>\r\n<p>SITHASC205 Produce Asian salads *</p>\r\n<p>SITHASC206 Produce Asian rice and noodles *</p>\r\n<p>SITHASC207 Produce curry pastes and powders *</p>\r\n<p>SITHASC301 Produce Asian cooked dishes *</p>\r\n<p>SITHASC302 Produce Asian desserts *</p>\r\n<p>SITHASC303 Produce Japanese cooked dishes *</p>\r\n<p>SITHASC304 Produce sashimi *</p>\r\n<p>SITHASC305 Produce sushi *</p>\r\n<p>SITHASC306 Produce Japanese desserts *</p>\r\n<p>SITHASC307 Produce dim sum *</p>\r\n<p>SITHASC308 Produce Chinese roast meat and poultry dishes *</p>\r\n<p>SITHASC309 Produce tandoori dishes *</p>\r\n<p>SITHASC310 Produce Indian breads *</p>\r\n<p>SITHASC311 Produce Indian sweetmeats *</p>\r\n<p>SITHASC312 Produce Indian pickles and chutneys *</p>\r\n<p>*Prerequisite is SITXFSA101 Use hygienic practices for food safety</p>\r\n<p>Client and Customer Service&nbsp;</p>\r\n<p>SITXCCS303 Provide service to customers</p>\r\n<p>SITXCCS401 Enhance the customer service experience</p>\r\n<p>Commercial Cookery and Catering&nbsp;</p>\r\n<p>SITHCCC104 Package prepared foodstuffs *</p>\r\n<p>SITHCCC205 Produce cook-chill and cook freeze foods *</p>\r\n<p>SITHCCC206 Rethermalise chilled and frozen foods *</p>\r\n<p>SITHCCC304 Produce and serve food for buffets *</p>\r\n<p>SITHCCC305 Produce pates and terrines *</p>\r\n<p>SITHCCC306 Handle and serve cheese *</p>\r\n<p>SITHCCC401 Produce specialised food items *</p>\r\n<p>SITHCCC402 Prepare portion-controlled meat cuts *</p>\r\n<p>*Prerequisite is SITXFSA101 Use hygienic practices for food safety</p>\r\n<p>Communication and Teamwork&nbsp;</p>\r\n<p>BSBCMM401A Make a presentation</p>\r\n<p>Computer Operations and ICT Management&nbsp;</p>\r\n<p>BSBITU201A Produce simple word processed documents</p>\r\n<p>BSBITU202A Create and use spreadsheets</p>\r\n<p>BSBITU203A Communicate electronically</p>\r\n<p>BSBITU306A Design and produce business documents</p>\r\n<p>BSBWOR204A Use business technology</p>\r\n<p>Events&nbsp;</p>\r\n<p>SITXEVT401 Plan in-house events or functions</p>\r\n<p>Finance&nbsp;</p>\r\n<p>BSBFIA301A Maintain financial records</p>\r\n<p>BSBFIA302A Process payroll</p>\r\n<p>BSBFIA303A Process accounts payable and receivable</p>\r\n<p>BSBFIA401A Prepare financial reports</p>\r\n<p>SITXFIN401 Interpret financial information</p>\r\n<p>Food and Beverage&nbsp;</p>\r\n<p>SITHFAB201 Provide responsible service of alcohol</p>\r\n<p>SITHFAB202 Operate a bar *^</p>\r\n<p>SITHFAB204 Prepare and serve espresso coffee *</p>\r\n<p>SITHFAB304 Provide advice on beers, spirits and liqueurs ^</p>\r\n<p>SITHFAB305 Provide advice on Australian wines ^</p>\r\n<p>SITHFAB306 Provide advice on imported wines ^</p>\r\n<p>SITHFAB307 Provide table service of food and beverage *^</p>\r\n<p>SITHFAB308 Provide silver service *</p>\r\n<p>SITHFAB309 Provide advice on food</p>\r\n<p>SITHFAB310 Provide advice on food and beverage matching ^</p>\r\n<p>SITHFAB311 Provide gueridon service *</p>\r\n<p>*Prerequisite is SITXFSA101 Use hygienic practices for food safety</p>\r\n<p>^Prerequisite is SITHFAB201 Provide responsible service of alcohol</p>\r\n<p>Food Safety&nbsp;</p>\r\n<p>SITXFSA202 Transport and store food</p>\r\n<p>SITXFSA401 Develop and implement a food safety program</p>\r\n<p>Human Resource Management&nbsp;</p>\r\n<p>SITXHRM401 Roster staff</p>\r\n<p>TAEASS301B Contribute to assessment</p>\r\n<p>TAEDEL301A Provide work skill instruction</p>\r\n<p>TAEDEL404A Mentor in the workplace</p>\r\n<p>Inventory&nbsp;</p>\r\n<p>SITXINV201 Receive and store stock</p>\r\n<p>SITXINV301 Purchase goods</p>\r\n<p>SITXINV401 Control stock</p>\r\n<p>Kitchen Operations&nbsp;</p>\r\n<p>SITHKOP401 Plan and display buffets *</p>\r\n<p>SITHKOP404 Plan catering for events or functions</p>\r\n<p>*Prerequisite is SITXFSA101 Use hygienic practices for food safety</p>\r\n<p>Management and Leadership&nbsp;</p>\r\n<p>BSBHRM403B Support performance-management processes</p>\r\n<p>BSBMGT405A Provide personal leadership</p>\r\n<p>Marketing and Public Relations&nbsp;</p>\r\n<p>SITXMPR401 Coordinate production of brochures and marketing materials</p>\r\n<p>SITXMPR403 Plan and implement sales activities</p>\r\n<p>SITXMPR404 Coordinate marketing activities</p>\r\n<p>Merchandising&nbsp;</p>\r\n<p>SIRXMER201 Merchandise products</p>\r\n<p>Patisserie&nbsp;</p>\r\n<p>SITHPAT302 Produce gateaux, torten and cakes *</p>\r\n<p>SITHPAT305 Produce petits fours *</p>\r\n<p>SITHPAT401 Prepare and model marzipan *</p>\r\n<p>SITHPAT402 Produce chocolate confectionery *</p>\r\n<p>SITHPAT403 Model sugar based decorations *</p>\r\n<p>SITHPAT404 Design and produce sweet buffet showpieces *</p>\r\n<p>*Prerequisite is SITXFSA101 Use hygienic practices for food safety</p>\r\n<p>Quality and Innovation&nbsp;</p>\r\n<p>BSBINN201A Contribute to workplace innovation</p>\r\n<p>Small Business Management&nbsp;</p>\r\n<p>BSBSMB401A Establish legal and risk management requirements of small business</p>\r\n<p>BSBSMB403A Market the small business</p>\r\n<p>BSBSMB404A Undertake small business planning</p>\r\n<p>Work Health and Safety&nbsp;</p>\r\n<p>SITXWHS301 Identify hazards, assess and control safety risks</p>\r\n<p>Working in Industry&nbsp;&nbsp;</p>\r\n<p>CHCAC318B Work effectively with older people</p>\r\n<p>SITHIND201 Source and use information on the hospitality industry</p>\r\n<p>&nbsp;</p>\r\n<p>Examples of elective units relevant to specific job outcomes and contexts at this level are as follows:</p>\r\n<p>&nbsp;</p>\r\n<p>Caterer in small catering operation&nbsp;</p>\r\n<p>BSBSMB401A Establish legal and risk management requirements of small business</p>\r\n<p>BSBSMB403A Market the small business</p>\r\n<p>BSBSMB404A Undertake small business planning</p>\r\n<p>BSBWRT401A Write complex documents</p>\r\n<p>SITHKOP401 Plan and display buffets</p>\r\n<p>SITHKOP404 Plan catering for events or functions</p>\r\n<p>&nbsp;</p>\r\n<p>Chef de partie in a large hotel kitchen&nbsp;</p>\r\n<p>BSBWRT401A Write complex documents</p>\r\n<p>SITHCCC401 Produce specialised food items</p>\r\n<p>SITHKOP401 Plan and display buffets</p>\r\n<p>SITHKOP404 Plan catering for events or functions</p>\r\n<p>SITXFIN401 Interpret financial information</p>\r\n<p>SITXHRM401 Roster staff</p>\r\n<p>&nbsp;</p>\r\n<p>Chef in a cafe or small restaurant&nbsp;</p>\r\n<p>SITHFAB204 Prepare and serve espresso coffee</p>\r\n<p>SITHFAB309 Provide advice on food</p>\r\n<p>SITHKOP404 Plan catering for events or functions</p>\r\n<p>SITXCCS401 Enhance the customer service experience</p>\r\n<p>SITXFSA401 Develop and implement a food safety program</p>\r\n<p>SITXINV301 Purchase goods</p>\r\n<p>&nbsp;</p>\r\n<p>Kitchen supervisor in an aged care facility&nbsp;</p>\r\n<p>BSBITU306A Design and produce business documents</p>\r\n<p>CHCAC318B Work effectively with older people</p>\r\n<p>SITHKOP404 Plan catering for events or functions</p>\r\n<p>SITXHRM401 Roster staff</p>\r\n<p>SITXINV301 Purchase goods</p>\r\n<p>SITXINV401 Control stock</p>\r\n</div>', NULL, '43.jpg', 'SIT40516.pdf', 1, '2021-04-27 01:41:37', '2021-06-02 02:49:28'),
(79, 1, 14, 1, 25, 'SIT40716', 'Certificate IV in Patisserie', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of pastry chefs who have a supervisory or team leading role in the kitchen. They operate independently or with limited guidance from others and use discretion to solve non-routine problems.</p>\r\n<p>&nbsp;</p>\r\n<p>This qualification provides a pathway to work in various organisations where patisserie products are prepared and served, including patisseries, restaurants, hotels, catering operations, clubs, pubs, caf&eacute;s, and coffee shops.</p>\r\n<p>&nbsp;</p>\r\n<p>Possible job titles include:</p>\r\n<ul>\r\n<li>chef de partie</li>\r\n<li>chef patissier.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>There are no entry requirements for this qualification.</p>\r\n<h2>Packaging Rules</h2>\r\n<p>32 units must be completed:</p>\r\n<ul>\r\n<li>26 core units</li>\r\n<li>6 elective units, consisting of:</li>\r\n</ul>\r\n<ul>\r\n<li>6 units from the list below, elsewhere in the SIT Training Package, or any other current Training Package or accredited course.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>The selection of electives must be guided by the job outcome sought, local industry requirements and the complexity of skills appropriate to the AQF level of this qualification.</p>\r\n<p>&nbsp;</p>\r\n<table width=\"801\">\r\n<tbody>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Core units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>BSBDIV501</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Manage diversity in the workplace</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>BSBSUS401</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Implement and monitor environmentally sustainable work practices</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHCCC001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Use food preparation equipment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHCCC005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare dishes using basic methods of cookery</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHCCC011</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Use cookery skills effectively</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHCCC018</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare food to meet special dietary requirements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHKOP005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Coordinate cooking operations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHPAT001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Produce cakes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHPAT002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Produce gateaux, torten and cakes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHPAT003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Produce pastries</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHPAT004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Produce yeast-based bakery products</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHPAT005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Produce petits fours</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHPAT006</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Produce desserts</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHPAT007</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare and model marzipan</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHPAT008</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Produce chocolate confectionery</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHPAT009</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Model sugar-based decorations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHPAT010</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Design and produce sweet buffet showpieces</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXCOM005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Manage conflict</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXFIN003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Manage finances within a budget</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXFSA001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Use hygienic practices for food safety</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXFSA002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Participate in safe food handling practices</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXHRM001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Coach others in job skills</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXHRM003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Lead and manage people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXINV002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Maintain the quality of perishable items</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXMGT001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Monitor work operations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXWHS003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Implement and monitor work health and safety practices</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Elective units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Client and Customer Service&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXCCS006</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide service to customers</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXCCS007</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Enhance customer service experiences</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Commercial Cookery and Catering&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHCCC008</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare vegetable, fruit, egg and farinaceous dishes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHCCC015</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Produce and serve food for buffets</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHCCC021</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare specialised food items</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Computer Operations and ICT Management&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>BSBITU202</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Create and use spreadsheets</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>BSBITU301</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Create and use databases</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>BSBITU306</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Design and produce business documents</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Finance&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>BSBFIA401</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare financial reports</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXFIN002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Interpret financial information</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>First Aid&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>HLTAID003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide first aid</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Food and Beverage&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB005</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Prepare and serve espresso coffee</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB007</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Serve food and beverage</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHFAB019</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Plan and monitor espresso coffee service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Food Safety&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXFSA003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Transport and store food</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXFSA004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Develop and implement a food safety program</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Human Resource Management&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXHRM002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Roster staff</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>TAEASS301B</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Contribute to assessment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>TAEDEL301A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Provide work skill instruction</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>TAEDEL404A</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Mentor in the workplace</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Inventory&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXINV001</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Receive and store stock</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXINV003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Purchase goods</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXINV004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Control stock</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Kitchen Operations and Management&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHKOP002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Plan and cost basic menus</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHKOP003</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Plan and display buffets</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHKOP004</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Develop menus for special dietary requirements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHKOP006</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Plan catering for events or functions</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Work Health and Safety&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITXWHS002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Identify hazards, assess and control safety risks</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"801\">\r\n<p>Working in Industry&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>SITHIND002</p>\r\n</td>\r\n<td width=\"593\">\r\n<p>Source and use information on the hospitality industry</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '44.jpg', 'SIT40716.pdf', 1, '2021-04-27 01:42:14', '2021-06-02 02:49:53'),
(80, 1, 7, 1, 25, 'TAE40116', 'Certificate IV in Training and Assessment', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the roles of individuals delivering training and assessment services in the vocational education and training (VET) sector.</p>\r\n<p>This qualification (or the skill sets derived from units of competency within it) is also suitable preparation for those engaged in the delivery of training and assessment of competence in a workplace context, as a component of a structured VET program.</p>\r\n<p>The volume of learning of a Certificate IV in Training and Assessment is typically six months to two years.</p>\r\n<p>Licensing/Regulatory Information&nbsp;&nbsp;</p>\r\n<p>Achievement of this qualification by trainers is a requirement of the Standards for Registered Training Organisations (RTOs) 2015.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Those entering this program must be able to demonstrate vocational competency in their proposed teaching and assessing area. Vocational competency is defined as broad industry knowledge and experience, and may include, but is not limited to, holding a relevant unit of competency or qualification.</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 10&nbsp;</p>\r\n<p>9 core units&nbsp; plus</p>\r\n<p>1 elective unit&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>The elective unit may be:</p>\r\n<ul>\r\n<li>from the elective list below</li>\r\n<li>from any currently endorsed Training Package or accredited course at Certificate IV or above.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>The elective unit chosen must be relevant to the work outcome and meet local industry needs.</p>\r\n<p>&nbsp;</p>\r\n<p>Core Units&nbsp;</p>\r\n<p>TAEASS401 Plan assessment activities and processes</p>\r\n<p>TAEASS402 Assess competence</p>\r\n<p>TAEASS403 Participate in assessment validation</p>\r\n<p>TAEASS502 Design and develop assessment tools</p>\r\n<p>TAEDEL401 Plan, organise and deliver group-based learning</p>\r\n<p>TAEDEL402 Plan, organise and facilitate learning in the workplace</p>\r\n<p>TAEDES401 Design and develop learning programs</p>\r\n<p>TAEDES402 Use training packages and accredited courses to meet client needs</p>\r\n<p>TAELLN411 Address adult language, literacy and numeracy skills</p>\r\n<p>&nbsp;</p>\r\n<p>Elective Units&nbsp;</p>\r\n<p>TAEASS301 Contribute to assessment</p>\r\n<p>TAEDEL301 Provide work skill instruction</p>\r\n<p>TAEDEL403 Coordinate and facilitate distance-based learning</p>\r\n<p>TAEDEL404 Mentor in the workplace</p>\r\n<p>TAEDEL501 Facilitate e-learning</p>\r\n<p>TAELLN412 Access resources and support to address foundation skills</p>\r\n<p>TAELLN413 Integrate foundation skills into vocational training delivery</p>\r\n<p>TAETAS401 Maintain training and assessment information</p>\r\n<p>TAEXDB401 Plan and implement individual support plans for learners with disability</p>\r\n<p>BSBAUD402 Participate in a quality audit</p>\r\n<p>BSBCMM401 Make a presentation</p>\r\n<p>BSBLED401 Develop teams and individuals</p>\r\n<p>BSBMKG413 Promote products and services</p>\r\n<p>BSBREL402 Build client relationships and business networks</p>\r\n<p>BSBRES401 Analyse and present research information</p>', NULL, '68.jpg', 'TAE40116.pdf', 1, '2021-04-27 01:42:59', '2021-06-02 02:52:17'),
(81, 1, 10, 1, 25, 'TLI41816', 'Certificate IV in Warehousing Operations', '<h2>Qualification Description</h2>\r\n<table width=\"909\">\r\n<tbody>\r\n<tr>\r\n<td width=\"909\">\r\n<p>This is a general qualification for the Warehousing and Storage Industry.</p>\r\n<p>It involves a broad range of skilled applications including requirements to evaluate and analyse current practices, to develop new criteria and procedures for performing current practices, and to provide leadership and guidance to others in applying skills and planning skill development.</p>\r\n<p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h2>Entry Requirements</h2>\r\n<p>There are no entry requirements for this qualification.</p>\r\n<p>&nbsp;</p>\r\n<h2>Packaging Rules</h2>\r\n<table width=\"850\">\r\n<tbody>\r\n<tr>\r\n<td colspan=\"2\" width=\"850\">\r\n<p>A total of 21 units of competency comprising:</p>\r\n<p>3 core units&nbsp; listed below&nbsp;plus&nbsp;</p>\r\n<p>18 general elective units&nbsp; from the general elective units listed below. Up to&nbsp;3 of the general elective units&nbsp;&nbsp;may be selected from any relevant nationally endorsed Training Package or accredited course. The general elective units must contribute to the vocational outcomes of the qualification.</p>\r\n<p>Where imported units are selected, care must be taken to ensure that all prerequisite units specified are complied with.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"850\">\r\n<p>Core units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIF0001</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Apply chain of responsibility legislation, regulations and workplace procedures</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIF1001</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Follow work health and safety procedures</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIL1001</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Complete workplace orientation/induction procedures</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"850\">\r\n<p>General elective units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIA4025</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Regulate temperature controlled stock</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIA4028</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Assess and monitor optimum stock levels</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIA4031</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Consolidate freight</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIA4032</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Organise transport of freight or goods</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLID2010</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Operate a forklift</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIE4006</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Collect, analyse and present workplace data and information</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIE4013</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Apply workplace statistics</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIF0002</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Administer chain of responsibility policies and procedures</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIF4007</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Implement and coordinate accident-emergency procedures</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIF4014</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Develop and maintain a safe workplace</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIG3002</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Lead a work team or group</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIG4005</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Organise transport workload</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIG4006</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Facilitate work teams</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLII4001</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Coordinate quality customer service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLII4005</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Market services and products to clients</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIJ3002</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Apply quality systems</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIL4005</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Apply conflict/grievance resolution strategies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIL4009</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Manage personal work priorities and professional development</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIL4010</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Assess and confirm customer transport requirements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIL4021</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Coordinate the erection and dismantling of temporary storage facilities</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIL4032</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Implement equal employment equity strategies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIL4033</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Promote effective workplace practice</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIL4036</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Develop rosters</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIL4037</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Apply and amend rosters</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLILIC0003</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Licence to operate a forklift truck</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLILIC0004</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Licence to operate an order picking forklift truck</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIM4004</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Mentor individuals or small groups</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIP4001</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Develop plans to meet customer and organisation needs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIP4002</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Facilitate and capitalise on change in the workplace</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIP4005</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Manage workplace information</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIP4031</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Maintain customer credit accounts and services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIR4001</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Monitor supplier performance</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIR4002</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Source goods/services and evaluate contractors</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIU0001</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Develop workplace policy and procedures for environmental sustainability</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIU3011</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Implement and monitor environmentally sustainable work practices</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"158\">\r\n<p>TLIU4001</p>\r\n</td>\r\n<td width=\"692\">\r\n<p>Implement and monitor environmental protection policies and procedures</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '96.jpg', 'TLI41816.pdf', 1, '2021-04-27 01:45:14', '2021-06-02 02:53:37');
INSERT INTO `courses` (`id`, `action_user`, `course_industries_id`, `qualification_id`, `course_categories_id`, `course_code`, `course_name`, `course_desc`, `rto`, `thumbnail`, `checklist`, `isPublished`, `created_at`, `updated_at`) VALUES
(82, 1, 7, 1, 25, 'TLI42016', 'Certificate IV in Logistics', '<h2>Description</h2>\r\n<p>Rationale&nbsp;:</p>\r\n<p>A qualification for those working in the Logistics Industry in a variety of operational roles.</p>\r\n<p>Successful completion will require the performance of a broad range of skilled applications including requirements to evaluate and analyse current practices, develop new criteria and procedure for performing current practices, and provision of some leadership and guidance to others in the application and planning of the skills.</p>\r\n<p>Successful completion of the licensing units within the qualification must align with applicable licensing and regulatory requirements.</p>\r\n<p>Job roles&nbsp;:</p>\r\n<p>Job roles and titles vary across different sectors. Possible job titles relevant to this qualification include:</p>\r\n<ul>\r\n<li>Logistics Coordinator</li>\r\n<li>Logistics Supervisor</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h2>Pathways Information</h2>\r\n<p>Not Applicable</p>\r\n<h2>Licensing/Regulatory Information</h2>\r\n<p>Refer to Description</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Not Applicable</p>\r\n<h2>Employability Skills Summary</h2>\r\n<p>Employability Skills Summary for&nbsp;</p>\r\n<p>TLI42010&nbsp;Certificate IV in Logistics&nbsp;</p>\r\n<p>The following table contains a summary of the employability skills as identified by the Transport and Logistics Industry for this qualification. This table should be interpreted in conjunction with the detailed requirements of each unit of competency packaged in this qualification. The outcomes described here are broad industry requirements that may vary depending on packaging options.</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"267\">\r\n<p>Employability Skill&nbsp;</p>\r\n</td>\r\n<td width=\"731\">\r\n<p>Industry&nbsp;/enterprise requirements for this qualification include&nbsp;:</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"267\">\r\n<p>Communication&nbsp;</p>\r\n</td>\r\n<td width=\"731\">\r\n<ul>\r\n<li>Establish and implement communication systems and procedures required for activities involved in the transport and logistics industry</li>\r\n<li>Listen to and interpret verbal information related to activities particularly when clarifying and confirming work requirements and receiving operational feedback</li>\r\n<li>Read and interpret relevant work requirements, policies, procedures, applicable to activities involved in transport and logistics industry</li>\r\n<li>Speak clearly and directly on diverse and complex matters when sharing data, requirements and procedures relevant to operations, communicating operational details to internal and external stakeholders and providing support and feedback to others</li>\r\n<li>Write documents to audience needs as part of duties, including when preparing risk assessment and plans, communicating with internal and external stakeholders, contributing to the documentation of specifications and tenders, and preparing information to contribute to technical reports</li>\r\n<li>Share information when preparing and obtaining necessary resources, to manage work activities and to ensure understanding of objectives and work plans</li>\r\n<li>Responsibly negotiate complex issues with others to resolve conflicts and to obtain the resources necessary to achieve objectives</li>\r\n<li>Use numeracy effectively to understand operational and costing data, to perform calculations and to contribute to estimates of resource requirements</li>\r\n<li>Recognise and interpret non-verbal signs, signals and behaviour</li>\r\n<li>Establish and use networks involvement in business or professional networks and to build relationships to provide benefits for the team and organisation.</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"267\">\r\n<p>Teamwork&nbsp;</p>\r\n</td>\r\n<td width=\"731\">\r\n<ul>\r\n<li>Work as an individual and a team member in a range of situations when planning and conducting operations, maintaining strong working relationships, ensuring safety, coordinating activities and resolving conflicts within team</li>\r\n<li>Provide leadership to staff</li>\r\n<li>Motivate others in the workplace</li>\r\n<li>Collaborate with others in the course of activities involved in the transport and logistics industry</li>\r\n<li>Define a role as part of a team including identifying the strengths of team members, understanding relationships between team members and understanding the roles and relationship between and among manager, team leaders, supervisors, etc.</li>\r\n<li>Manage the avoidance and prevention of harassment of others in the workplace</li>\r\n<li>Work with persons of different ages, gender, race, religion, political persuasion, etc.</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"267\">\r\n<p>Problem solving&nbsp;</p>\r\n</td>\r\n<td width=\"731\">\r\n<ul>\r\n<li>Develop practical solutions for problems arising in the course of activities including assessing hazards and ensuring there are plans or processes to manage identified risks, monitoring issues which arise in the course of operations and adjust activities and to creating, implementing and applying risk management systems</li>\r\n<li>Monitor and anticipate problems that may occur in the course of activities involved in the transport and logistics industry including hazards and risks and take appropriate action to report or resolve the problems within limits of responsibility</li>\r\n<li>Solve problems in teams including allocating roles and responsibilities in response to changes in environment or circumstances, coordinating requirements and issues, and evaluating and monitoring performance</li>\r\n<li>Show independence and initiative in identifying problems and solving them</li>\r\n<li>Resolve customer concerns in relations to complex project issues including resolving contract issues, meeting quality requirements and meeting deadlines.</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"266\">\r\n<p>Initiative and enterprise&nbsp;</p>\r\n</td>\r\n<td width=\"732\">\r\n<ul>\r\n<li>Modify activities dependent on differing work situations and contingencies</li>\r\n<li>Take appropriate initiatives in a diverse range of operational situations such as those above</li>\r\n<li>Recognise and respond to changes in internal an external operating environments</li>\r\n<li>Contribute to and manage continuous improvement processes</li>\r\n<li>Be creative in approaches to change and innovation, in response to conflicts in coordination and allocation of resources and in both in encouraging input from staff and interactions between and amongst staff and teams</li>\r\n<li>Value input from staff</li>\r\n<li>Manage the response to any contingencies and changes in equipment, standard operating procedures and the working environment.</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"266\">\r\n<p>Planning and organising&nbsp;</p>\r\n</td>\r\n<td width=\"732\">\r\n<ul>\r\n<li>Implement and monitor operational and emergency plans, systems and procedures</li>\r\n<li>Allocate people and other resources to tasks including adapting allocations to cope with contingencies, delegating tasks and responsibilities to capable staff and clearly defining responsibilities</li>\r\n<li>Prepare scope of work and work plans for self and team members</li>\r\n<li>Implement and monitor systems and procedures for maintaining compliance with regulations and codes of practice</li>\r\n<li>Monitor the implementation of the workplace security and safety management systems (where applicable)</li>\r\n<li>Monitor, evaluate and report on operational performance and compliance</li>\r\n<li>Collect, analyse, interpret and organise information needed when supervising activities involved in the transport and logistics industry</li>\r\n<li>Be resourceful in planning for and assessing risk</li>\r\n<li>Ensure feedback and other data contribute to improvements in operational effectiveness</li>\r\n<li>Manage time and priorities in the course of activities involved in the transport and logistics industry.</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"267\">\r\n<p>Self management&nbsp;</p>\r\n</td>\r\n<td width=\"731\">\r\n<ul>\r\n<li>Interpret and apply relevant regulations and instructions</li>\r\n<li>Establish and follow own work plans and schedules</li>\r\n<li>Evaluate and monitor own work performance</li>\r\n<li>Take responsibility for meeting own objectives</li>\r\n<li>Have confidence in own vision and goals</li>\r\n<li>Develop trust and confidence in staff and customers</li>\r\n<li>Maintain effective networks.</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"267\">\r\n<p>Learning&nbsp;</p>\r\n</td>\r\n<td width=\"731\">\r\n<ul>\r\n<li>Organise learning and assessment activities for others in the workplace</li>\r\n<li>Manage adaptation of self and others in the workplace to any changes in systems, equipment and procedures and the workplace operating environment</li>\r\n<li>Be open to new ideas and change and in particular facilitate and support change processes with staff and apply previous experience and feedback in formulating improvements to practice</li>\r\n<li>Provide opportunities for instruction, coaching and mentoring others in the workplace as required</li>\r\n<li>Contribute to the assessment of the competence of others in the workplace</li>\r\n<li>Contribute to the creation of a learning community in the workplace</li>\r\n<li>Adapt own competence in response to any changes in activities involved in the transport and logistics industry</li>\r\n<li>Update own knowledge and skills required for activities involved in the transport and logistics industry.</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"267\">\r\n<p>Technology&nbsp;</p>\r\n</td>\r\n<td width=\"731\">\r\n<ul>\r\n<li>Use complex equipment and IT systems required during activities involved in the transport and logistics industry</li>\r\n<li>Apply a range of basic IT skills</li>\r\n<li>Use IT to organise and access data including the monitoring of logistics processes, the tracking of items and the recording and reporting of system status</li>\r\n<li>Applying IT as a management tool to store and organise data</li>\r\n<li>Implement and monitor operational and maintenance procedures and systems for equipment used during activities involved in the transport and logistics industry</li>\r\n<li>Implement and monitor the application of OH&amp;S procedures when using IT and office equipment and facilities.</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Requirements for completion of the qualification&nbsp;:</p>\r\n<p>A successful assessment outcome for a total of&nbsp;14 units&nbsp; of competency comprising:</p>\r\n<ul>\r\n<li>1&nbsp;core&nbsp;unit&nbsp; listed below</li>\r\n</ul>\r\n<p>plus</p>\r\n<ul>\r\n<li>7 technical elective units&nbsp; from the selected list below</li>\r\n</ul>\r\n<p>plus</p>\r\n<ul>\r\n<li>6 elective units&nbsp; which may be taken from the elective units listed below, the remaining technical elective units listed below, or may include up to 3 units drawn with appropriate contextualisation from this Training Package, and/or other relevant nationally endorsed Training Package or accredited course.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Where imported units are selected, care must be taken to ensure that all pre-requisites specified are complied with.</p>\r\n<p>Core unit&nbsp;:</p>\r\n<table width=\"936\">\r\n<tbody>\r\n<tr>\r\n<td width=\"313\">\r\n<p>Field&nbsp;</p>\r\n</td>\r\n<td width=\"623\">\r\n<p>Unit&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"313\">\r\n<p>X&nbsp;Logistics&nbsp;</p>\r\n</td>\r\n<td width=\"623\">\r\n<p>TLIX4028A Apply knowledge of logistics</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Technical elective units&nbsp;:</p>\r\n<table width=\"936\">\r\n<tbody>\r\n<tr>\r\n<td width=\"316\">\r\n<p>Field&nbsp;</p>\r\n</td>\r\n<td width=\"620\">\r\n<p>Unit&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"316\">\r\n<p>A&nbsp;Handling Cargo&nbsp;/Stock&nbsp;</p>\r\n</td>\r\n<td width=\"620\">\r\n<p>TLIA4028A Assess and monitor optimum stock levels</p>\r\n<p>TLIA4032A Organise transport of freight or goods</p>\r\n<p>TLIA4033A Organise international transport of freight</p>\r\n<p>TLIA4062A Implement safety stock systems</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"316\">\r\n<p>E&nbsp;Communication and Calculation&nbsp;</p>\r\n</td>\r\n<td width=\"620\">\r\n<p>TLIE3002A Estimate/calculate mass, area and quantify dimensions</p>\r\n<p>TLIE4013A Apply workplace statistics</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"316\">\r\n<p>F&nbsp;Safety Management&nbsp;</p>\r\n</td>\r\n<td width=\"620\">\r\n<p>TLIF4014A Develop and maintain a safe workplace</p>\r\n<p>TLIF3063A Administer the implementation of fatigue management strategies</p>\r\n<p>TLIF4065A Ensure compliance with Australian Dangerous Goods Code</p>\r\n<p>TLIF4066A Implement and supervise transport regulations compliance systems</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"316\">\r\n<p>G&nbsp;Teamwork&nbsp;</p>\r\n</td>\r\n<td width=\"620\">\r\n<p>TLIG4005A Organise transport workload</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"316\">\r\n<p>I&nbsp;Customer Service&nbsp;</p>\r\n</td>\r\n<td width=\"620\">\r\n<p>TLII4001A Coordinate quality customer service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"316\">\r\n<p>L&nbsp;Resource Management&nbsp;</p>\r\n</td>\r\n<td width=\"620\">\r\n<p>TLIL4030A Control furniture warehouse</p>\r\n<p>TLIL4070A Work effectively in the transport and logistics industry</p>\r\n<p>TLIL4078A Coordinate fleet control logistics</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"316\">\r\n<p>P&nbsp;Administration and Finance&nbsp;</p>\r\n</td>\r\n<td width=\"620\">\r\n<p>TLIP4003A Implement, maintain and evaluate dangerous goods transport procedures within the workplace</p>\r\n<p>TLIP4013A Implement and monitor logistics planning and process</p>\r\n<p>TLIP4038A Monitor a supply chain operation</p>\r\n<p>TLIP4039A Monitor transport operations</p>\r\n<p>TLIP4040A Monitor warehouse operations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"316\">\r\n<p>R&nbsp;Contract Procurement&nbsp;</p>\r\n</td>\r\n<td width=\"620\">\r\n<p>TLIR4001A Monitor supplier performance</p>\r\n<p>TLIR4002A Source goods/services and evaluate contractors</p>\r\n<p>TLIR4003A Negotiate a contract</p>\r\n<p>TLIR4008A Implement and supervise stocktaking procedures</p>\r\n<p>TLIR4009A Implement purchasing systems</p>\r\n<p>TLIR4010A Plan purchasing</p>\r\n<p>TLIR4012A Conduct international purchasing</p>\r\n<p>PSPPROC411A Plan procurement</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"316\">\r\n<p>U&nbsp;Environment&nbsp;</p>\r\n</td>\r\n<td width=\"620\">\r\n<p>TLIU3011A Implement and monitor environmentally sustainable work practices</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Elective units&nbsp;:</p>\r\n<table width=\"936\">\r\n<tbody>\r\n<tr>\r\n<td width=\"326\">\r\n<p>Field&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>Unit&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>A&nbsp;Handling Cargo&nbsp;/Stock&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>TLIA4005A Check and evaluate records and documentation</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>D&nbsp;Load Handling&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>TLID1001A Shift materials safely using manual handling methods</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>E&nbsp;Communication and Calculation&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>TLIE3012A Consolidate manifest documentation</p>\r\n<p>PSPGOV406B Gather and analyse information</p>\r\n<p>PSPGOV413A Compose complex workplace documents</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>F&nbsp;Safety Management&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>BSBOHS407A Monitor a safe workplace</p>\r\n<p>HLTFA311A Apply first aid</p>\r\n<p>HLTFA412A Apply advanced first aid</p>\r\n<p>TLIF3093A Implement chain of responsibility regulations</p>\r\n<p>TLIF4007A Implement and coordinate accident-emergency procedures</p>\r\n<p>TLIF4094A Ensure compliance with chain of responsibility</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>G&nbsp;Teamwork&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>TLIG4006A Facilitate work teams</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>I&nbsp;Customer Service&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>BSBCUS401B Coordinate implementation of customer service strategies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>J&nbsp;Quality&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>TLIJ4008A Implement and monitor inbound QA systems</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>K&nbsp;Technology&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>TLIK2010A Use infotechnology devices in the workplace</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>L&nbsp;Resource Management&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>TLIL4005A Apply conflict/grievance resolution strategies</p>\r\n<p>TLIL4009A Manage personal work priorities and professional development</p>\r\n<p>TLIL4036A Develop rosters</p>\r\n<p>TLIL4037A Apply and amend rosters</p>\r\n<p>TLIL4058A Plan a career in logistics</p>\r\n<p>TLIL4059A Implement asset management systems</p>\r\n<p>BSBHRM402A Recruit, select and induct staff</p>\r\n<p>BSBMGT403A Implement continuous improvement</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>LIC&nbsp;Licensing Units&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>TLILIC2001A Licence to operate a forklift truck</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>P&nbsp;Administration and Finance&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>BSBRSK401A Identify risk and apply risk management processes</p>\r\n<p>PSPGOV404B Develop and implement work unit plans</p>\r\n<p>SITXFIN004A Manage finances within a budget</p>\r\n<p>TLIP4001A Develop plans to meet customer and organisation needs</p>\r\n<p>TLIP4002A Facilitate and capitalise on change in the workplace</p>\r\n<p>TLIP4005A Manage workplace information</p>\r\n<p>TLIP4028A Administer international trading accounts</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>R&nbsp;Contract Procurement&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>PSPPROC411A Plan procurement</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"326\">\r\n<p>U&nbsp;Environment&nbsp;</p>\r\n</td>\r\n<td width=\"610\">\r\n<p>TLIU2012A Participate in environmentally sustainable work practices</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '69.jpg', 'TLI42016.pdf', 1, '2021-04-27 01:45:43', '2021-06-02 02:55:50'),
(83, 1, 28, 1, 26, 'AUR50216', 'Diploma of Automotive Technology', '<h2>Description</h2>\r\n<p>This qualification covers the skills and knowledge required to diagnose, analyse, evaluate, design and modify automotive electrical and mechanical systems. It is suitable for those working within the automotive industry at the forefront of the implementation of new technologies.</p>\r\n<p>Job roles&nbsp;/employment outcomes&nbsp;</p>\r\n<p>The Diploma of Automotive Technology is intended to prepare new employees or recognise and develop existing workers who are performing advanced diagnosis and design tasks in the automotive industry.</p>\r\n<p>&nbsp;</p>\r\n<p>Employment outcomes targeted by this qualification include:</p>\r\n<ul>\r\n<li>advanced diagnostic technician</li>\r\n<li>automotive system designer.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Application&nbsp;</p>\r\n<p>This qualification is suitable for an Australian Apprenticeship pathway.</p>\r\n<h2>Pathways Information</h2>\r\n<p>Pathways into the qualification&nbsp;</p>\r\n<p>Entrants to this qualification are required to have completed AUR40208 Certificate IV in Automotive Technology or be able to demonstrate equivalent competence.</p>\r\n<p>&nbsp;</p>\r\n<p>Pathways from the qualification&nbsp;</p>\r\n<p>Further training pathways from this qualification may lead to a relevant Advanced Diploma.</p>\r\n<p>&nbsp;</p>\r\n<p>Additional qualification advice&nbsp;</p>\r\n<p>Because technology is increasing at an exponential rate and to ensure qualification relevance and integrity, industry recommends that this qualification be completed within a specified time of approximately five (5) years.</p>', NULL, '53.jpg', 'AUR50216.pdf', 1, '2021-04-27 01:55:11', '2021-06-01 05:27:14'),
(84, 1, 10, 1, 26, 'BSB50215', 'Diploma of Business', '<h2>Qualification Description</h2>\r\n<p>This qualification would apply to individuals with various job titles including executive officers, program consultants and program coordinators.</p>\r\n<p>Individuals in these roles may possess substantial experience in a range of settings, but seek to further develop their skills across a wide range of business functions.</p>\r\n<p>Conversely, it may also apply to those with little or no vocational experience, but who possess sound theoretical business skills and knowledge that they would like to develop in order to create further educational and employment opportunities.</p>\r\n<p>&nbsp;</p>\r\n<h4>Licensing/Regulatory Information</h4>\r\n<p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Nil</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 8&nbsp;</p>\r\n<p>This qualification has no core units.&nbsp;</p>\r\n<p>8 elective units must be selected, of which:&nbsp;&nbsp;</p>\r\n<ul>\r\n<li>6 of the elective units must be selected from the units listed below, with no more than 3 units selected from any one group</li>\r\n<li>2 elective units may be selected from elective units listed below, from the BSB Business Services Training Package, or from any current accredited course or endorsed Training Package at this qualification level or Certificate IV or Advanced Diploma level.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<h4>Elective Units</h4>\r\n<h4>Group A</h4>\r\n<p>BSBADV503 Coordinate advertising research</p>\r\n<p>BSBADV507 Develop a media plan</p>\r\n<p>BSBADV509 Create mass print media advertisements</p>\r\n<p>BSBADV510 Create mass electronic media advertisements</p>\r\n<p>BSBMKG523 Design and develop an integrated marketing communication plan</p>\r\n<p>BSBWRT501 Write persuasive copy</p>\r\n<p>&nbsp;</p>\r\n<h4>Group B</h4>\r\n<p>BSBADM502 Manage meetings</p>\r\n<p>BSBADM503 Plan and manage conferences</p>\r\n<p>BSBADM504 Plan and implement administrative systems</p>\r\n<p>BSBADM506 Manage business document design and development</p>\r\n<p>BSBEBU511 Develop and implement an e-business strategy</p>\r\n<p>BSBFIM502 Manage payroll</p>\r\n<p>BSBITB511 Establish and maintain a network of digital devices</p>\r\n<p>BSBXCM501 Lead communication in the workplace</p>\r\n<p>&nbsp;</p>\r\n<h4>Group C</h4>\r\n<p>BSBHRM501 Manage human resources services</p>\r\n<p>BSBHRM502 Manage human resources management information systems</p>\r\n<p>BSBHRM513 Manage workforce planning</p>\r\n<p>BSBHRM505 Manage remuneration and employee benefits</p>\r\n<p>BSBHRM506 Manage recruitment, selection and induction processes</p>\r\n<p>BSBHRM507 Manage separation or termination</p>\r\n<p>BSBHRM509 Manage rehabilitation or return-to-work programs</p>\r\n<p>BSBHRM510 Manage mediation processes</p>\r\n<p>BSBLED502 Manage programs that promote personal effectiveness</p>\r\n<p>BSBXDB501 Support staff members with disability in the workplace</p>\r\n<p>BSBXDB502 Adapt organisations to enhance accessibility for people with disability</p>\r\n<p>&nbsp;</p>\r\n<h4>Group D</h4>\r\n<p>BSBMKG501 Identify and evaluate marketing opportunities</p>\r\n<p>BSBMKG502 Establish and adjust the marketing mix</p>\r\n<p>BSBMKG506 Plan market research</p>\r\n<p>BSBMKG507 Interpret market trends and developments</p>\r\n<p>BSBMKG508 Plan direct marketing activities</p>\r\n<p>BSBMKG509 Implement and monitor direct marketing activities</p>\r\n<p>BSBMKG510 Plan e-marketing communications</p>\r\n<p>BSBMKG514 Implement and monitor marketing activities</p>\r\n<p>BSBMKG515 Conduct a marketing audit</p>\r\n<p>BSBPUB501 Manage the public relations publication process</p>\r\n<p>BSBPUB502 Develop and manage complex public relations campaigns</p>\r\n<p>BSBPUB503 Manage fundraising and sponsorship activities</p>\r\n<p>BSBPUB504 Develop and implement crisis management plans</p>\r\n<p>&nbsp;</p>\r\n<h4>Group E</h4>\r\n<p>BSBCON601 Develop and maintain business continuity plans</p>\r\n<p>BSBINM501 Manage an information or knowledge management system</p>\r\n<p>BSBINN501 Establish systems that support innovation</p>\r\n<p>BSBINN502 Build and sustain an innovative work environment</p>\r\n<p>BSBIPR501 Manage intellectual property to protect and grow business</p>\r\n<p>BSBMGT403 Implement continuous improvement</p>\r\n<p>BSBPMG522 Undertake project work</p>\r\n<p>BSBRSK501 Manage risk</p>\r\n<p>BSBSUS501 Develop workplace policy and procedures for sustainability</p>\r\n<p>BSBWOR501 Manage personal work priorities and professional development</p>\r\n<p>BSBXBD501 Develop big data strategy</p>', 'Bright College,Unique College of Technology', '97.jpg', 'BSB50215.pdf', 1, '2021-04-27 02:34:02', '2021-06-02 02:05:05'),
(85, 1, 10, 1, 26, 'BSB50415', 'Diploma of Business Administration', '<h2>Qualification Description</h2>\r\n<p>This qualification would apply to individuals with various job titles including administration managers, general office managers and office managers. Individuals in these roles may possess a sound theoretical knowledge base and use a range of specialised, technical or managerial competencies to plan, carry out and evaluate their own work and/or the work of a team.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Licensing/Regulatory Information&nbsp;</strong>&nbsp;</p>\r\n<p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Nil</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 8&nbsp;</p>\r\n<p>This qualification has no core units&nbsp;</p>\r\n<p>8 elective units, of which:&nbsp;</p>\r\n<ul>\r\n<li>5 elective units must be selected from the Group A units listed below</li>\r\n<li>3 elective units may be selected from the Group B units listed below, or any currently endorsed Training Package or accredited course at the same qualification level</li>\r\n<li>if not listed below, 1 unit may be selected from either a Certificate IV or Advanced Diploma qualification.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<h2>Elective Units&nbsp;</h2>\r\n<p>Group A&nbsp;</p>\r\n<p>BSBADM502 Manage meetings</p>\r\n<p>BSBADM503 Plan and manage conferences</p>\r\n<p>BSBADM504 Plan and implement administrative systems</p>\r\n<p>BSBADM506 Manage business document design and development</p>\r\n<p>BSBFIM502 Manage payroll</p>\r\n<p>BSBITB511 Establish and maintain a network of digital devices</p>\r\n<p>BSBPMG522 Undertake project work</p>\r\n<p>&nbsp;</p>\r\n<p>Group B units&nbsp;</p>\r\n<p>BSBCUS501 Manage quality customer service</p>\r\n<p>BSBINM501 Manage an information or knowledge management system</p>\r\n<p>BSBINN301 Promote innovation in a team environment</p>\r\n<p>BSBMGT502 Manage people performance</p>\r\n<p>BSBRKG502 Manage and monitor business or records systems</p>\r\n<p>BSBSUS501 Develop workplace policy and procedures for sustainability</p>\r\n<p>BSBWOR501 Manage personal work priorities and professional development</p>\r\n<p>BSBWOR502 Lead and manage team effectiveness</p>', NULL, '98.jpg', 'BSB50415.pdf', 1, '2021-04-27 02:35:44', '2021-06-02 02:06:06'),
(86, 1, 10, 1, 26, 'BSB50615', 'Diploma of Human Resources Management', '<h2>Description</h2>\r\n<p>This qualification reflects the role of individuals who have a sound theoretical knowledge base in human resources management and demonstrate a range of managerial skills to ensure that human resources functions are effectively conducted in an organisation or business area. Typically they would have responsibility for the work of other staff.</p>\r\n<p><strong>Job roles&nbsp;</strong></p>\r\n<ul>\r\n<li>Human resources adviser</li>\r\n<li>Human resources and change manager</li>\r\n<li>Human resources consultant</li>\r\n<li>Human resources manager</li>\r\n<li>Senior human resources officer.</li>\r\n</ul>\r\n<h2>Pathways Information</h2>\r\n<p>Pathways into the qualification&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Preferred pathways for candidates considering this qualification include:</p>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li>BSB41013 Certificate IV in Human Resources or other relevant qualifications</li>\r\n</ul>\r\n<p>OR</p>\r\n<ul>\r\n<li>with vocational experience in human resources management, but without formal qualifications.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Examples of indicative job roles for candidates seeking entry based on their vocational experience include:</p>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li>Human resources assistant</li>\r\n<li>Human resources coordinator</li>\r\n<li>Human resources administrator</li>\r\n<li>Human resources officer</li>\r\n<li>Payroll officer.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Pathways from the qualification&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li>BSB60407 Advanced Diploma of Management</li>\r\n<li>BSB60907 Advanced Diploma of Management (Human Resources)</li>\r\n<li>other Advanced Diploma qualifications.</li>\r\n</ul>\r\n<h2>Licensing/Regulatory Information</h2>\r\n<p>There is no direct link between this qualification and licensing, legislative and/or regulatory requirements. However, where required, a unit of competency will specify relevant licensing, legislative and/or regulatory requirements that impact on the unit.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>There are no entry requirements for this qualification.</p>\r\n<h2>Employability Skills Summary</h2>\r\n<p>The following table contains a summary of the employability skills required by industry for this qualification. The employability skills facets described here are broad industry requirements that may vary depending on qualification packaging options.</p>\r\n<p>&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"284\">\r\n<p>Employability skill&nbsp;</p>\r\n</td>\r\n<td width=\"733\">\r\n<p>Industry/enterprise requirements for this qualification include:&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"284\">\r\n<p>Communication</p>\r\n</td>\r\n<td width=\"733\">\r\n<ul>\r\n<li>consulting with internal and external stakeholders</li>\r\n<li>interviewing, counselling, negotiating and acting as an advocate for the organisation</li>\r\n<li>questioning to clarify and evaluate information</li>\r\n<li>writing in a range of styles to suit different audiences</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"284\">\r\n<p>Teamwork</p>\r\n</td>\r\n<td width=\"733\">\r\n<ul>\r\n<li>treating team members with integrity, respect and empathy</li>\r\n<li>working with others and clearly identifying the roles and responsibilities of the human resources team, line managers and external contractors</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"284\">\r\n<p>Problem-solving</p>\r\n</td>\r\n<td width=\"733\">\r\n<ul>\r\n<li>conducting cost-benefit analyses, determining salary packaging, and assessing and managing risk</li>\r\n<li>generating a range of options to resolve human resources issues</li>\r\n<li>identifying appropriate data-gathering techniques for training needs analyses</li>\r\n<li>managing organisational change and diversity</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"284\">\r\n<p>Initiative and enterprise</p>\r\n</td>\r\n<td width=\"733\">\r\n<ul>\r\n<li>being responsive to change and translating ideas into innovative solutions</li>\r\n<li>promoting flexible work practices and encouraging diversity</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"284\">\r\n<p>Planning and organising</p>\r\n</td>\r\n<td width=\"733\">\r\n<ul>\r\n<li>analysing strategic and operational plans in order to plan, deliver and evaluate the human resources service delivery or agreement</li>\r\n<li>collecting, collating and analysing information using appropriate workplace business systems</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"284\">\r\n<p>Self-management</p>\r\n</td>\r\n<td width=\"733\">\r\n<ul>\r\n<li>complying with legislative and statutory requirements</li>\r\n<li>planning own work, predicting consequences and identifying improvements</li>\r\n<li>presenting a professional image when representing the organisation</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"284\">\r\n<p>Learning</p>\r\n</td>\r\n<td width=\"733\">\r\n<ul>\r\n<li>supporting the implementation of learning and development initiatives as identified by performance review processes</li>\r\n<li>identifying and providing training support</li>\r\n<li>mentoring and coaching others</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"284\">\r\n<p>Technology</p>\r\n</td>\r\n<td width=\"733\">\r\n<ul>\r\n<li>selecting and using technology to record, track and retrieve information</li>\r\n<li>selecting appropriate human resources systems</li>\r\n<li>using electronic communication devices and processes, such as internet, intranet and email to produce written correspondence and reports</li>\r\n<li>using technology to facilitate change, assist the management of information, and assist the planning process</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 9&nbsp;</p>\r\n<p>6 core units&nbsp;&nbsp;plus&nbsp;</p>\r\n<p>3 elective units&nbsp;, of which:</p>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li>at least 2 units must be from the elective units listed below</li>\r\n<li>1 unit may be from an accredited course or any endorsed Training Package at Certificate IV level or above.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Elective units chosen must be relevant to the work outcome and industry context for human resources.</p>\r\n<p>&nbsp;</p>\r\n<p>Core units&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>BSBHRM501B Manage human resources services</p>\r\n<p>BSBHRM506A Manage recruitment selection and induction processes</p>\r\n<p>BSBHRM512A Develop and manage performance-management processes</p>\r\n<p>BSBHRM513A Manage workforce planning</p>\r\n<p>BSBWRK510A Manage employee relations</p>\r\n<p>BSBWHS401A Implement and monitor WHS policies, procedures and programs to meet legislative requirements</p>\r\n<p>&nbsp;</p>\r\n<p>Elective units&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>BSBDIV501A Manage diversity in the workplace</p>\r\n<p>BSBFIM501A Manage budgets and financial plans</p>\r\n<p>BSBFIM502A Manage payroll</p>\r\n<p>BSBHRM502A Manage human resources management information systems</p>\r\n<p>BSBHRM505B Manage remuneration and employee benefits</p>\r\n<p>BSBHRM507A Manage separation or termination</p>\r\n<p>BSBHRM509A Manage rehabilitation or return to work programs</p>\r\n<p>BSBHRM510A Manage mediation processes</p>\r\n<p>BSBHRM511A Manage expatriate staff</p>\r\n<p>BSBINM501A Manage an information or knowledge management system</p>\r\n<p>BSBINN601B Manage organisational change</p>\r\n<p>BSBITU402A Develop and use complex spreadsheets</p>\r\n<p>BSBLED501A Develop a workplace learning environment</p>\r\n<p>BSBLED502A Manage programs that promote personal effectiveness</p>\r\n<p>BSBMGT502B Manage people performance</p>\r\n<p>BSBMGT516C Facilitate continuous improvement</p>\r\n<p>BSBPMG522A Undertake project work</p>\r\n<p>BSBRKG502B Manage and monitor business or records system</p>\r\n<p>BSBRSK501B Manage risk</p>\r\n<p>BSBSUS501A Develop workplace policy and procedures for sustainability</p>\r\n<p>BSBWHS501A Ensure a safe workplace</p>\r\n<p>BSBWHS506A Contribute to developing, implementing and maintaining WHS management systems</p>', NULL, '99.jpg', 'BSB50615.pdf', 1, '2021-04-27 02:37:26', '2021-06-02 02:06:55'),
(87, 1, 10, 1, 26, 'BSB50815', 'Diploma of International Business', '<h2>Description</h2>\r\n<p>This qualification reflects the role of individuals who possess a sound theoretical knowledge base in international business management and demonstrate a range of managerial skills to ensure that international business activities are conducted effectively in an organisation or business area. Typically they would have responsibility for the work of other staff and lead teams in conducting international business activities.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Job roles&nbsp;</strong></p>\r\n<p>Job roles and titles vary across different industry sectors. Possible job titles relevant to this qualification include:</p>\r\n<ul>\r\n<li>export manager</li>\r\n<li>import manager</li>\r\n<li>trade manager.</li>\r\n</ul>\r\n<h2>Pathways Information</h2>\r\n<p>Pathways into the qualification&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Preferred pathways for candidates considering this qualification include:</p>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li>BSB41107 Certificate IV in International Trade or other relevant qualification</li>\r\n</ul>\r\n<p>OR</p>\r\n<ul>\r\n<li>with vocational experience working in an international business environment but without formal international business qualifications.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Pathways from the qualification&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li>BSB60207 Advanced Diploma of Business or other Advanced Diploma qualifications.</li>\r\n</ul>\r\n<h2>Licensing/Regulatory Information</h2>\r\n<p>There is no direct link between this qualification and licensing, legislative or regulatory requirements. However, where required, a unit of competency will specify relevant licensing, legislative or regulatory requirements that impact on the unit.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>There are no entry requirements for this qualification.</p>\r\n<h2>Employability Skills Summary</h2>\r\n<p>The following table contains a summary of the employability skills required by industry for this qualification. The employability skills facets described here are broad industry requirements that may vary depending on qualification packaging options.</p>\r\n<p>&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"273\">\r\n<p>Employability skill&nbsp;</p>\r\n</td>\r\n<td width=\"744\">\r\n<p>Industry or enterprise requirements for this qualification include:&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"273\">\r\n<p>Communication</p>\r\n</td>\r\n<td width=\"744\">\r\n<ul>\r\n<li>communicating ideas and information taking into consideration international clients&rsquo; diverse social and cultural needs</li>\r\n<li>developing international business networks and maintaining relationships domestically and internationally</li>\r\n<li>using excellent interpersonal skills and producing a wide range of reports and visual presentations</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"273\">\r\n<p>Teamwork</p>\r\n</td>\r\n<td width=\"744\">\r\n<ul>\r\n<li>coaching and mentoring staff and others in conducting businesses in new and unusual environments</li>\r\n<li>defining performance measures and working collaboratively with team members</li>\r\n<li>delegating and briefing various personnel on their roles and responsibilities regarding the implementation of organisational plans</li>\r\n<li>managing and providing feedback on individual and team performance</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"273\">\r\n<p>Problem-solving</p>\r\n</td>\r\n<td width=\"744\">\r\n<ul>\r\n<li>assessing the financial viability of new opportunities and matching organisational capability with market needs</li>\r\n<li>developing a range of options in response to difficulties arising from conducting business in a complex environment</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"273\">\r\n<p>Initiative and enterprise</p>\r\n</td>\r\n<td width=\"744\">\r\n<ul>\r\n<li>developing new approaches and innovative strategies to increase performance</li>\r\n<li>identifying new and emerging opportunities for the business and developing strategies to capitalise on them</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"273\">\r\n<p>Planning and organising</p>\r\n</td>\r\n<td width=\"744\">\r\n<ul>\r\n<li>allocating resources to meet organisational requirements</li>\r\n<li>collecting, collating and analysing information using appropriate workplace business systems</li>\r\n<li>evaluating and assessing product performance in international markets</li>\r\n<li>planning for contingencies to ensure client needs are met</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"273\">\r\n<p>Self-management</p>\r\n</td>\r\n<td width=\"744\">\r\n<ul>\r\n<li>managing own time effectively</li>\r\n<li>meeting compliance requirements</li>\r\n<li>working within organisational policies and procedures and legislative requirements</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"273\">\r\n<p>Learning</p>\r\n</td>\r\n<td width=\"744\">\r\n<ul>\r\n<li>determining staff needs for re-training or induction to new systems, and new skill development</li>\r\n<li>providing learning and development opportunities to team members</li>\r\n<li>updating own knowledge on social, economic, political and business trends in international environments</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"273\">\r\n<p>Technology</p>\r\n</td>\r\n<td width=\"744\">\r\n<ul>\r\n<li>creating presentations using a range of media</li>\r\n<li>using business technology, such as computers, word processing and document management software</li>\r\n<li>using online technologies for research and marketing purposes</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 8&nbsp;</p>\r\n<p>8 elective units&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>5 elective units&nbsp; must be selected from the Group A units listed below.</p>\r\n<p>&nbsp;</p>\r\n<p>1 elective unit&nbsp; must be selected from either the Group A units or Group B units listed below.</p>\r\n<p>&nbsp;</p>\r\n<p>2 elective units&nbsp; may be selected from the Group A or Group B units listed below, from this Training Package or from any current accredited course or endorsed Training Package at this qualification level or Certificate IV or Advanced Diploma level.</p>\r\n<p>&nbsp;</p>\r\n<p>Elective units must be relevant to the work outcome, local industry requirements and the qualification level.</p>\r\n<p>&nbsp;</p>\r\n<p>Group A&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Financial administration&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBFIA501A Report on finances related to international business</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Marketing&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBMKG511A Analyse data from international markets</p>\r\n<p>BSBMKG512A Forecast international market and business needs</p>\r\n<p>BSBMKG513A Promote products and services to international markets</p>\r\n<p>BSBMKG516B Profile international markets</p>\r\n<p>BSBMKG517A Analyse consumer behaviour for specific international markets</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Relationship management&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBREL501A Build international client relationships</p>\r\n<p>BSBREL502A Build international business networks</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Group B&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Customer service&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBCUS501C Manage quality customer service</p>\r\n<p>&nbsp;</p>\r\n<p>Financial management&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>BSBFIM501A Manage budgets and financial plans</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Information management&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBINM501A Manage an information or knowledge management system</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Innovation&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBINN501A Establish systems that support innovation</p>\r\n<p>BSBINN502A Build and sustain an innovative work environment</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Learning and development&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBLED501A Develop a workplace learning environment</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Management&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBMGT502B Manage people performance</p>\r\n<p>BSBMGT515A Manage operational plan</p>\r\n<p>BSBMGT516C Facilitate continuous improvement</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Work health and safety&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBWHS501A Ensure a safe workplace</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Project management&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBPMG521A Manage project integration</p>\r\n<p>BSBPMG511A Manage project scope</p>\r\n<p>BSBPMG512A Manage project time</p>\r\n<p>BSBPMG513A Manage project quality</p>\r\n<p>BSBPMG514A Manage project costs</p>\r\n<p>BSBPMG515A Manage project human resources</p>\r\n<p>BSBPMG516A Manage project information and communications</p>\r\n<p>BSBPMG517A Manage project risk</p>\r\n<p>BSBPMG518A Manage project procurement</p>\r\n<p>BSBPMG522A Undertake project work</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Risk management&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBRSK501B Manage risk</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Sustainability&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBSUS501A Develop workplace policy and procedures for sustainability</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Workplace effectiveness&nbsp;</strong></p>\r\n<p>&nbsp;</p>\r\n<p>BSBWOR501B Manage personal work priorities and professional development</p>\r\n<p>BSBWOR502B Ensure team effectiveness</p>', NULL, '93.jpg', 'BSB50815.pdf', 1, '2021-04-27 02:37:56', '2021-06-02 02:09:59');
INSERT INTO `courses` (`id`, `action_user`, `course_industries_id`, `qualification_id`, `course_categories_id`, `course_code`, `course_name`, `course_desc`, `rto`, `thumbnail`, `checklist`, `isPublished`, `created_at`, `updated_at`) VALUES
(88, 1, 27, 1, 26, 'BSB51315', 'Diploma of Work Health and Safety', '<section id=\"overview\">\r\n<h2>Overview</h2>\r\n<div>\r\n<p>The Diploma of Work Health and Safety will assist you in effective WHS risk management, lead response and incident investigation. You will also learn to develop workplace policy and procedures for sustainability and the environment.</p>\r\n</div>\r\n<p>Career opportunities, include:</p>\r\n<ul>\r\n<li>OHS/WHS manager</li>\r\n<li>human resources manager</li>\r\n<li>OHS/WHS consultant and advisor</li>\r\n<li>OHS/WHS practitioner</li>\r\n</ul>\r\n<p>Pathways to further study:</p>\r\n<ul>\r\n<li>BSB60619 Advanced Diploma of Work Health and Safety</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<h2>Studying the Diploma of Work Health and Safety at Holmesglen</h2>\r\n<p>More than ever before, looking after the wellbeing of employees, visitors and customers is of vital importance to organisations.</p>\r\n<p>The Diploma of Work Health and Safety is for people managing, coordinating and maintaining the work health and safety (WHS) program or the Occupational/Work Health and Safety Management System (OHSMS/WHSMS) in an organisation.</p>\r\n<p>The units of competency contained in this qualification will assist participants in managing the expectations of the ISO45001, AS/NZS4801, AS/NZS9001 and the AS/NZS14001.</p>\r\n<p>Our diploma course also contains the BSBWHS512 Contribute to managing work related psychological health and safety. This gives participants a thorough understanding of how to manage the risks associated with mental health in the workplace.</p>\r\n<p>The course will help you develop your management and leadership skills. You will learn how to manage WHS procedures, quality systems and how to streamline processes to minimise risks associated with work related operations.</p>\r\n</section>\r\n<section id=\"course-structure\">\r\n<h2>Course structure</h2>\r\n<p>&nbsp;</p>\r\n<p>Students typically attend one evening a week. Evening classes run every Tuesday night from 6pm to 9pm. Classes won&rsquo;t run in a week with a public holiday.</p>\r\n<p>Elective units have been chosen by Holmesglen based on feedback from industry as well as subject matter experts. If you have already completed other elective units, these may contribute towards completion of this course.</p>\r\n<p>&nbsp;</p>\r\n<h3>Units</h3>\r\n<div>\r\n<div data-wg=\"Accordion\">\r\n<div data-toggle=\"collapse\" data-parent=\"#accordionContainerId3\" aria-expanded=\"false\" aria-controls=\"accordionId13\">View units</div>\r\n</div>\r\n</div>\r\n<h3>Assessment</h3>\r\n<p>Assessments are designed to provide learners with opportunities to demonstrate they have attained the required skills and knowledge using a range of practically based activities and tasks, as required by recognised standards.</p>\r\n</section>\r\n<section id=\"requirements\">\r\n<h2>Entry requirements</h2>\r\n<p>A good command of the English language, both written and verbal, is recommended.<br />Minimum 18 Years of age.</p>\r\n<p>All BSB41419 Certificate IV in Work Health and Safety core units or equivalent competencies. Equivalent competencies are predecessors to the following units which have been mapped as equivalent.<br />BSBWHS412 Assist with workplace compliance with WHS laws<br />BSBWHS413 Contribute to implementation and maintenance of WHS consultation and participation processes<br />BSBWHS414 Contribute to WHS risk management<br />BSBWHS415 Contribute to implementing WHS management systems<br />BSBWHS416 Contribute to workplace incident response</p>\r\n<p>Prior to enrollment or commencement of training you will be required to complete a literacy and numeracy assessment and a pre-training interview. These will assist with determining your suitability to the course, verify your training plan, and identify and learning support needs.</p>\r\n<h3>Recognition of prior learning</h3>\r\n<p>You may be able to shorten the length of your chosen course by measuring skills acquired through work, life experiences or qualifications obtained from formal studies or training. AQF qualifications and statements of attainment issued by another registered training organisation will be recognised by Holmesglen.</p>\r\n</section>\r\n<section id=\"outcomes\">\r\n<h2>Outcomes</h2>\r\n<h3>Qualification and recognition</h3>\r\n<p>After the completion of the program, you will receive the certificate of BSB51319 Diploma of Work Health and Safety.</p>\r\n</section>', NULL, '52.jpg', 'BSB51315.pdf', 1, '2021-04-27 02:38:44', '2021-06-02 02:48:20'),
(89, 1, 12, 1, 26, 'BSB51415', 'Diploma of Project Management', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of individuals who apply project management skills and knowledge. They may manage projects in a variety of contexts, across a number of industry sectors. They have project leadership and management roles and are responsible for achieving project objectives. They possess a sound theoretical knowledge base and use a range of specialised, technical and managerial competencies to initiate, plan, execute and evaluate their own work and/or the work of others.</p>\r\n<p>&nbsp;</p>\r\n<h4>Licensing/Regulatory Information</h4>\r\n<p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Nil</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 12&nbsp;</p>\r\n<p>8 core units&nbsp; plus</p>\r\n<p>4 elective units, of which:&nbsp;</p>\r\n<ul>\r\n<li>4 elective units&nbsp; may be selected from the elective units listed below or any endorsed Training Package or accredited course at Diploma level or higher.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome. They must not include the choice of the unit BSBPMG522 Undertake project work.</p>\r\n<p>&nbsp;</p>\r\n<h4>Core Units</h4>\r\n<p>BSBPMG511 Manage project scope</p>\r\n<p>BSBPMG512 Manage project time</p>\r\n<p>BSBPMG513 Manage project quality</p>\r\n<p>BSBPMG514 Manage project cost</p>\r\n<p>BSBPMG515 Manage project human resources</p>\r\n<p>BSBPMG516 Manage project information and communication</p>\r\n<p>BSBPMG517 Manage project risk</p>\r\n<p>BSBPMG521 Manage project integration</p>\r\n<p>&nbsp;</p>\r\n<h4>Elective Units</h4>\r\n<p>BSBINM501 Manage an information or knowledge management system</p>\r\n<p>BSBINN502 Build and sustain an innovative work environment</p>\r\n<p>BSBMGT516 Facilitate continuous improvement</p>\r\n<p>BSBPMG518 Manage project procurement</p>\r\n<p>BSBPMG519 Manage project stakeholder engagement</p>\r\n<p>BSBPMG520 Manage project governance</p>\r\n<p>BSBSUS501 Develop workplace policy and procedures for sustainability</p>\r\n<p>BSBXBD501 Develop big data strategy</p>\r\n<p>BSBWHS516 Contribute to developing, implementing and maintaining an organisation&rsquo;s WHS management system</p>\r\n<p>BSBWOR501 Manage personal work priorities and professional development</p>\r\n<p>BSBWOR502 Lead and manage team effectiveness</p>\r\n<p>ICTICT511 Match ICT needs with the strategic direction of the enterprise</p>\r\n<p>ICTICT515 Verify client business requirements</p>\r\n<p>MSS015002 Develop strategies for more sustainable use of resources</p>\r\n<p>PSPETH003 Promote the values and ethos of public service</p>', NULL, '34.jpg', 'BSB51415.pdf', 1, '2021-04-27 02:39:24', '2021-06-02 02:49:00'),
(90, 1, 10, 1, 26, 'BSB51615', 'Diploma of Quality Auditing', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of individuals who possess a sound theoretical knowledge base and use a range of specialised, technical or managerial competencies to plan, carry out and evaluate their own work and/or the work of a team. They may work as quality assurance managers, quality facilitators, quality and improvement consultants or service quality system support analysts.</p>\r\n<p>&nbsp;</p>\r\n<p>Licensing/Regulatory Information</p>\r\n<p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Nil</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 8&nbsp;</p>\r\n<p>This qualification has no core units.&nbsp;</p>\r\n<p>8 elective units must be selected, of which:&nbsp;</p>\r\n<ul>\r\n<li>3 elective units must be selected from the Group A units listed below</li>\r\n<li>2 elective units must be selected from the Group A or Group B units listed below or from an equivalent level qualification within this Training Package</li>\r\n<li>3 elective units may be selected from the Group A or Group B units listed below, or any currently endorsed Training Package, or accredited course at the same qualification level</li>\r\n<li>if not listed below, 1 unit may be selected from either a Certificate IV or Advanced Diploma qualification.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<h3>Elective Units&nbsp;</h3>\r\n<p>Group A&nbsp;</p>\r\n<p>BSBAUD402 Participate in a quality audit</p>\r\n<p>BSBAUD501 Initiate a quality audit</p>\r\n<p>BSBAUD503 Lead a quality audit</p>\r\n<p>BSBAUD504 Report on a quality audit</p>\r\n<p>BSBINM501 Manage an information or knowledge management system</p>\r\n<p>BSBRSK501 Manage risk</p>\r\n<p>&nbsp;</p>\r\n<p>Group B&nbsp;</p>\r\n<p>BSBMGT502 Manage people performance</p>\r\n<p>BSBMGT516 Facilitate continuous improvement</p>\r\n<p>BSBPMG513 Manage project quality</p>\r\n<p>BSBSUS501 Develop workplace policy and procedures for sustainability</p>\r\n<p>BSBWOR502 Lead and manage team effectiveness</p>', NULL, '100.jpg', 'BSB51615.pdf', 1, '2021-04-27 02:47:55', '2021-06-02 02:49:44'),
(91, 1, 10, 1, 26, 'BSB51915', 'Diploma of Leadership and Management', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of individuals who apply knowledge, practical skills and experience in leadership and management across a range of enterprise and industry contexts.</p>\r\n<p>&nbsp;</p>\r\n<p>Individuals at this level display initiative and judgement in planning, organising, implementing and monitoring their own workload and the workload of others. They use communication skills to support individuals and teams to meet organisational or enterprise requirements.</p>\r\n<p>&nbsp;</p>\r\n<p>They plan, design, apply and evaluate solutions to unpredictable problems, and identify, analyse and synthesise information from a variety of sources.</p>\r\n<p>&nbsp;</p>\r\n<h4>Licensing/Regulatory Information</h4>\r\n<p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Nil</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 12&nbsp;</p>\r\n<p>4 core units&nbsp;&nbsp;plus</p>\r\n<p>8 elective units, of which:&nbsp;</p>\r\n<ul>\r\n<li>4 elective units must be selected from Group A</li>\r\n<li>up to 4 may be additional units from Group A or Group B</li>\r\n<li>if not listed below, up to 2 electives may be from Diploma or above in the Business Services Training Package</li>\r\n<li>if not listed below, 1 elective unit may be from any currently endorsed Training Package or accredited course at Diploma level.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<h4>Core Units</h4>\r\n<p>BSBLDR502 Lead and manage effective workplace relationships</p>\r\n<p>BSBLDR511 Develop and use emotional intelligence</p>\r\n<p>BSBMGT517 Manage operational plan</p>\r\n<p>BSBWOR502 Lead and manage team effectiveness</p>\r\n<p>&nbsp;</p>\r\n<h4>Elective Units</h4>\r\n<h4>Group A</h4>\r\n<p>BSBCUS501 Manage quality customer service</p>\r\n<p>BSBFIM501 Manage budgets and financial plans</p>\r\n<p>BSBHRM405 Support the recruitment, selection and induction of staff</p>\r\n<p>BSBINN502 Build and sustain an innovative work environment</p>\r\n<p>BSBIPR501 Manage intellectual property to protect and grow business</p>\r\n<p>BSBLDR504 Implement diversity in the workplace</p>\r\n<p>BSBLDR513 Communicate with influence</p>\r\n<p>BSBMGT502 Manage people performance</p>\r\n<p>BSBMGT516 Facilitate continuous improvement</p>\r\n<p>BSBMGT518 Develop organisation policy</p>\r\n<p>BSBMGT519 Incorporate digital solutions into plans and practices</p>\r\n<p>BSBMGT520 Plan and manage the flexible workforce</p>\r\n<p>BSBPMG522 Undertake project work</p>\r\n<p>BSBRSK501 Manage risk</p>\r\n<p>BSBWHS521 Ensure a safe workplace for a work area</p>\r\n<p>BSBWOR501 Manage personal work priorities and professional development</p>\r\n<p>&nbsp;</p>\r\n<h4>Group B</h4>\r\n<p>BSBADM502 Manage meetings</p>\r\n<p>BSBCOM503 Develop processes for the management of breaches in compliance requirements</p>\r\n<p>BSBFRA502 Manage a franchise operation</p>\r\n<p>BSBHRM511 Manage expatriate staff</p>\r\n<p>BSBHRM512 Develop and manage performance-management processes</p>\r\n<p>BSBHRM513 Manage workforce planning</p>\r\n<p>BSBINM501 Manage an information or knowledge management system</p>\r\n<p>BSBINN501 Establish systems that support innovation</p>\r\n<p>BSBLED501 Develop a workplace learning environment</p>\r\n<p>BSBMGT521 Plan, implement and review a quality assurance program</p>\r\n<p>BSBMKG507 Interpret market trends and developments</p>\r\n<p>BSBMKG512 Forecast international market and business needs</p>\r\n<p>BSBREL502 Build international business networks</p>\r\n<p>BSBSLS501 Develop a sales plan</p>\r\n<p>BSBSLS502 Lead and manage a sales team</p>\r\n<p>BSBSUS501 Develop workplace policy and procedures for sustainability</p>\r\n<p>BSBWRK520 Manage employee relations</p>\r\n<p>BSBXBD501 Develop big data strategy</p>\r\n<p>BSBXCM501 Lead communication in the workplace</p>', NULL, '101.jpg', 'BSB51915.pdf', 1, '2021-04-27 02:48:19', '2021-06-02 02:50:20'),
(92, 1, 10, 1, 26, 'BSB52415', 'Diploma of Marketing and Communication', '<h2>Qualification Description</h2>\r\n<p>This qualification applies to individuals with a sound theoretical knowledge base in marketing and communication and who demonstrate a range of managerial skills to ensure that functions are effectively conducted in an organisation or business area. Typically they would have responsibility for the work of other staff and lead teams.</p>\r\n<p>&nbsp;</p>\r\n<p>Licensing/Regulatory Information&nbsp;&nbsp;</p>\r\n<p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Entry to this qualification is limited to those individuals who:</p>\r\n<ul>\r\n<li>have completed all core units in BSB42415 Certificate IV in Marketing and Communication.</li>\r\n</ul>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 12&nbsp;</p>\r\n<p>3 core units&nbsp; plus</p>\r\n<p>9 elective&nbsp;&nbsp;units, of which:</p>\r\n<ul>\r\n<li>8 elective units must be selected from the electives listed below</li>\r\n<li>the remaining elective unit may be selected from the elective units listed below, or any currently endorsed Training Package or accredited course at Diploma or Advanced Diploma level.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Core Units&nbsp;</strong></p>\r\n<p>BSBMKG507 Interpret market trends and developments</p>\r\n<p>BSBMKG523 Design and develop an integrated marketing communication plan</p>\r\n<p>BSBPMG522 Undertake project work</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Elective Units&nbsp;</strong></p>\r\n<p>BSBADV503 Coordinate advertising research</p>\r\n<p>BSBADV507 Develop a media plan</p>\r\n<p>BSBADV509 Create mass print media advertisements</p>\r\n<p>BSBADV510 Create mass electronic media advertisements</p>\r\n<p>BSBCRT501 Originate and develop concepts</p>\r\n<p>BSBDES602 Research global design trends</p>\r\n<p>BSBEBU511 Develop and implement an e-business strategy</p>\r\n<p>BSBFIM501 Manage budgets and financial plans</p>\r\n<p>BSBIPR501 Manage intellectual property to protect and grow business</p>\r\n<p>BSBLDR502 Lead and manage effective workplace relationships</p>\r\n<p>BSBMKG501 Identify and evaluate marketing opportunities</p>\r\n<p>BSBMKG502 Establish and adjust the marketing mix</p>\r\n<p>BSBMKG506 Plan market research</p>\r\n<p>BSBMKG508 Plan direct marketing activities</p>\r\n<p>BSBMKG509 Implement and monitor direct marketing activities</p>\r\n<p>BSBMKG510 Plan e-marketing communications</p>\r\n<p>BSBMKG514 Implement and monitor marketing activities</p>\r\n<p>BSBMKG515 Conduct a marketing audit</p>\r\n<p>BSBMKG518 Plan and implement services marketing</p>\r\n<p>BSBMKG519 Plan and implement business-to-business marketing</p>\r\n<p>BSBMKG520 Manage compliance within the marketing legislative framework</p>\r\n<p>BSBMKG521 Plan and implement sponsorship and event marketing</p>\r\n<p>BSBMKG522 Plan measurement of marketing effectiveness</p>\r\n<p>BSBMKG528 Mine data to identify industry directions</p>\r\n<p>BSBMKG529 Manage client account</p>\r\n<p>BSBMKG530 Create distributed multiplatform digital advertisements</p>\r\n<p>BSBMKG534 Design effective digital user experiences</p>\r\n<p>BSBMKG535 Devise a seach engine optimisation strategy</p>\r\n<p>BSBMKG536 Develop strategies to monitise digital engagement</p>\r\n<p>BSBMKG537 Develop a social media engagement plan</p>\r\n<p>BSBPUB501 Manage the public relations publication process</p>\r\n<p>BSBPUB502 Develop and manage complex public relations campaigns</p>\r\n<p>BSBPUB503 Manage fundraising and sponsorship activities</p>\r\n<p>BSBPUB504 Develop and implement crisis management plans</p>\r\n<p>BSBWRT501 Write persuasive copy</p>\r\n<p>ICTGAM504 Manage interactive media production</p>', NULL, '102.jpg', 'BSB52415.pdf', 1, '2021-04-27 02:48:57', '2021-06-02 02:51:11'),
(93, 1, 12, 1, 26, 'CHC50113', 'Diploma of Early Childhood Education and Care', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of early childhood educators who are responsible for designing and implementing curriculum in early childhood education and care services. In doing so they work to implement an approved learning framework within the requirements of the Education and Care Services National Regulations and the National Quality Standard.</p>\r\n<p>They may have responsibility for supervision of volunteers or other staff.</p>\r\n<p>&nbsp;</p>\r\n<p>Under the Education and Care Services National Law (2011) the Australian Children&rsquo;s Education and Care Quality Authority (ACECQA) publishes lists of approved early childhood education and care qualifications and information regarding regulatory requirements here:&nbsp;www.acecqa.gov.au.</p>\r\n<p>&nbsp;</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 28</p>\r\n<ul>\r\n<li>23 core units</li>\r\n<li>5 elective units, of which:</li>\r\n</ul>\r\n<ul>\r\n<li>at least 2 must be selected from the elective units listed below</li>\r\n<li>up to 3 units may be selected from any endorsed Training Packages or accredited courses relevant to the work outcome</li>\r\n</ul>\r\n<p>All electives chosen must contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Core units&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCDIV002</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Promote Aboriginal and/or Torres Strait Islander cultural safety</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Develop cultural competence</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE002</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Ensure the health and safety of children</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE003</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Provide care for children</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE004</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Promote and provide healthy food and drinks</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE005</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Provide care for babies and toddlers</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE007</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Develop positive and respectful relationships with children</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE009</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Use an approved learning framework to guide practice</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE016</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Establish and maintain a safe and healthy environment for children</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE017</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Foster the holistic development and wellbeing of the child in early childhood</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE018</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Nurture creativity in children</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE019</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Facilitate compliance in an education and care services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE020</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Establish and implement plans for developing cooperative behaviour</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE021</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Implement strategies for the inclusion of all children</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE022</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Promote children&rsquo;s agency</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE023</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Analyse information to inform learning</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE024</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Design and implement the curriculum to foster children\'s learning and development</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE025</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Embed sustainable practices in service operations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE026</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Work in partnership with families to provide appropriate education and care for children</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCLEG001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Work legally and ethically</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCPRT001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Identify and respond to children and young people at risk</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>HLTAID004</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Provide an emergency first aid response in an education and care setting</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>HLTWHS003</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Maintain work health and safety</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Elective units&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"197\">\r\n<p>CHCDIV001</p>\r\n</td>\r\n<td width=\"775\">\r\n<p>Work with diverse people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"197\">\r\n<p>CHCINM002</p>\r\n</td>\r\n<td width=\"775\">\r\n<p>Meet community information needs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"197\">\r\n<p>CHCMGT003</p>\r\n</td>\r\n<td width=\"775\">\r\n<p>Lead the work team</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"197\">\r\n<p>CHCPOL002</p>\r\n</td>\r\n<td width=\"775\">\r\n<p>Develop and implement policy</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"197\">\r\n<p>CHCPOL003</p>\r\n</td>\r\n<td width=\"775\">\r\n<p>Research and apply evidence to practice</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"197\">\r\n<p>CHCPRP003</p>\r\n</td>\r\n<td width=\"775\">\r\n<p>Reflect on and improve own professional practice</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"197\">\r\n<p>CHCSAC005</p>\r\n</td>\r\n<td width=\"775\">\r\n<p>Foster the holistic development and wellbeing of the child in school age care</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"197\">\r\n<p>BSBINN502</p>\r\n</td>\r\n<td width=\"775\">\r\n<p>Build and sustain an innovative work environment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"197\">\r\n<p>BSBLED401</p>\r\n</td>\r\n<td width=\"775\">\r\n<p>Develop teams and individuals</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"197\">\r\n<p>BSBMGT605</p>\r\n</td>\r\n<td width=\"775\">\r\n<p>Provide leadership across the organisation</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"197\">\r\n<p>BSBSUS501</p>\r\n</td>\r\n<td width=\"775\">\r\n<p>Develop workplace policy and procedures for sustainability</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"197\">\r\n<p>PSPMNGT605B</p>\r\n</td>\r\n<td width=\"775\">\r\n<p>Manage diversity</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '35.jpg', 'CHC50113.pdf', 1, '2021-04-27 02:49:41', '2021-06-02 03:18:45');
INSERT INTO `courses` (`id`, `action_user`, `course_industries_id`, `qualification_id`, `course_categories_id`, `course_code`, `course_name`, `course_desc`, `rto`, `thumbnail`, `checklist`, `isPublished`, `created_at`, `updated_at`) VALUES
(94, 1, 7, 1, 26, 'CHC52015', 'Diploma of Community Services', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the roles of community services, case management and social housing workers involved in the managing, co-ordinating and/or delivering of person-centred services to individuals, groups and communities.</p>\r\n<p>&nbsp;</p>\r\n<p>At this level, workers have specialised skills in community services and work autonomously under broad directions from senior management. Workers are usually providing direct support to individuals or groups of individuals. Workers may also have responsibility for the supervision of other workers and volunteers and/or case management; program coordination or the development of new business opportunities.</p>\r\n<p>&nbsp;</p>\r\n<p>Note that the&nbsp;Statutory &amp; forensic child, youth &amp; family welfare&nbsp;specialisationmust be achieved in orderto meet the minimum education requirements for child protection and youth justice practice in Victoria. In addition, to meet the minimum education requirements for entry into child protection practice in Victoria, diploma qualifications must be approved by the Australian Community Workers Association (ACWA)</p>\r\n<p>&nbsp;</p>\r\n<p>To achieve this qualification, the candidate must have completed at least 100 hours of work as detailed in the Assessment Requirements of units of competency.</p>\r\n<p>&nbsp;</p>\r\n<p>No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 16</p>\r\n<ul>\r\n<li>8 core units</li>\r\n<li>8 elective units, consisting of:</li>\r\n</ul>\r\n<ul>\r\n<li>at least 6 units from the electives listed below</li>\r\n<li>up to 2 units from the electives listed below, any endorsed Training Packages or accredited courses &ndash; these units must be relevant to the work outcome</li>\r\n</ul>\r\n<p>Any combination of electives that meets the rules above can be selected for the award of the&nbsp;Diploma of Community Services.&nbsp;Where appropriate, electives may be packaged to provide a qualification with a specialisation.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Packaging for each specialisation:&nbsp;</p>\r\n<ul>\r\n<li>at least 4 Group A electives must be selected for award of the&nbsp;Diploma of Community Services&nbsp;(Case Management)</li>\r\n<li>at least 3 Group B electives must be selected for award of the&nbsp;Diploma of Community Services&nbsp;(Social Housing)</li>\r\n<li>all Group C electives must be selected for award of the Diploma of Community Services&nbsp;(Statutory &amp; forensic child, youth &amp; family welfare)</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>All electives chosen must contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Core units&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCCCS007</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Develop and implement service programs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCCOM003</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Develop workplace communication strategies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCDEV002</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Analyse impacts of sociological factors on clients in community work and services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCDIV003</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Manage and promote diversity</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCLEG003</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Manage legal and ethical compliance</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCMGT005</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Facilitate workplace debriefing and support processes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCPRP003</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Reflect on and improve own professional practice</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>HLTWHS004</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Manage work health and safety</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Elective units&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Group A electives &ndash; CASE MANAGEMENT specialisation&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCCCS004</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Assess co-existing needs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCCSM004</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Coordinate complex case requirements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCCSM005</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Develop, facilitate and review all aspects of case management</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCCSM006</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Provide case management supervision</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCCSM007</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Undertake case management in a child protection framework</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Group B electives &ndash; SOCIAL HOUSING specialisation&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCADV004</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Represent organisation in court or tribunal</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCSOH002</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Manage and maintain tenancy agreements and services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCSOH008</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Manage head lease</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCSOH009</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Develop quality systems in line with registration standards</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCSOH011</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Develop social housing enterprise opportunities</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CHCSOH012</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Acquire properties by purchase or transfer</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CPPDSM5005A</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Contribute to a detailed property feasibility study</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CPPDSM5013A</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Develop a tenancy mix strategy</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CPPDSM5022A</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Implement asset management plan</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CPPDSM5026A</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Manage a consultant property project team</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CPPDSM5034A</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Monitor performance of property or facility portfolio</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>CPPDSM6007A</p>\r\n</td>\r\n<td width=\"788\">\r\n<p>Develop lifecycle asset management plan</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Group C electives &ndash; STATUTORY &amp; FORENSIC CHILD, YOUTH &amp; FAMILY WELFARE specialisation&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CHCCCS004 &nbsp;&nbsp;</p>\r\n</td>\r\n<td width=\"781\">\r\n<p>Assess co-existing needs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CHCCSL001&nbsp;&nbsp;</p>\r\n</td>\r\n<td width=\"781\">\r\n<p>Establish and confirm the counselling relationship</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CHCCSM005</p>\r\n</td>\r\n<td width=\"781\">\r\n<p>Develop, facilitate and review all aspects of case management</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CHCCDE011 &nbsp;</p>\r\n</td>\r\n<td width=\"781\">\r\n<p>Implement community development strategies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CHCDEV001 &nbsp;&nbsp;&nbsp;</p>\r\n</td>\r\n<td width=\"781\">\r\n<p>Confirm client developmental status</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CHCMHS013</p>\r\n</td>\r\n<td width=\"781\">\r\n<p>Implement trauma informed care</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CHCPRT001 &nbsp;&nbsp;</p>\r\n</td>\r\n<td width=\"781\">\r\n<p>Identify and respond to children and young people at risk</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CHCPRT003 &nbsp;</p>\r\n</td>\r\n<td width=\"781\">\r\n<p>Work collaboratively to maintain an environment safe for children and young people</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Other electives&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCADV002</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide advocacy and representation services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCADV003</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Represent clients in court</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCADV005</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide systems advocacy services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCAGE001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Facilitate the empowerment of older people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCAOD004</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Assess needs of client with alcohol and other drugs issues</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCAOD005</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide alcohol and other drug withdrawal services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCAOD007</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop strategies for alcohol and other drugs relapse prevention and management</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCAOD008</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide advanced interventions to meet the needs of clients with alcohol and other drugs issues</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCAOD009</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop and review individual alcohol and other drugs treatment plans</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCCCS003</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Increase the safety of individuals at risk of suicide</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCCCS009</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Facilitate responsible behaviour</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCCCS019</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Recognise and respond to crisis situations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCCCS024</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Support individuals with autism spectrum disorder</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCCDE007</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop and provide community projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCCDE008</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Support community action</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCCDE009</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop and Support community leadership</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCCDE010</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop and lead community engagement strategies to enhance participation</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCCDE012</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Work within organisation and government structures to enable community development outcomes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCCDE015</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop and implement a community renewal plan</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCCOM004</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Present information to stakeholder groups</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCCSL002</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Apply specialist interpersonal and counselling interview skills</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCCSL003</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Facilitate the counselling relationship and process</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCCSL007</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Support counselling clients in decision-making processes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCDEV003</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Analyse client information for service planning and delivery</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCDFV006</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Counsel clients affected by domestic and family violence</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCDFV007</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Work with users of violence to effect change</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCDIS005</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop and provide person-centered service responses</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCDIS006</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop and promote positive person-centered behaviour supports</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCDIS008</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Facilitate community participation and social inclusion</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCDIS010</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide person-centered services to people with disability with complex needs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCDIV002</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Promote Aboriginal and/or Torres Strait Islander cultural safety</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCEDU002</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Plan health promotion and community intervention</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCEDU003</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide sexual and reproductive health information to clients</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCEDU004</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop, implement and review sexual and reproductive health education programs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCEDU009</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Provide parenting, health and well-being education</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCFAM001</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Operate in a family law environment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCFAM003</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Support people to improve relationships</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCFAM004</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Facilitate changeovers</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCFAM005</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Facilitate and monitor contact</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCFAM006</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Assist families to self-manage contact</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCGRP002</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Plan and conduct group activities</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCINM001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Meet statutory and organisation information requirements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCLLN001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Respond to client language, literacy and numeracy needs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMGT001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop, implement and review quality framework</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMGT002</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage partnership agreements with service providers</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMGT003</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Lead the work team</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMGT004</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Secure and manage funding</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMGT006</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Coordinate client directed services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMHS001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Work with people with mental health issues</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMHS002</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Establish a self-directed recovery relationship</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMHS003</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide recovery oriented mental health services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMHS004</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Work collaboratively with the care network and other services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMHS005</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide services to people with with co-existing mental health and alcohol and other drugs issues</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMHS006</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Facilitate the recovery process with the person, family and carers</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMHS008</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Promote and facilitate self advocacy</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCMHS011</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Assess and promote social, emotional and physical wellbeing</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCPOL002</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop and implement policy</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCPOL003</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Research and apply evidence to practice</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCPRP001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop and maintain networks and collaborative partnerships</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"216\">\r\n<p>CHCPRP003</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"773\">\r\n<p>Reflect on and improve own professional practice</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCPRP004</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Promote and represent the service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCPRP005</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Engage with health professionals and the health system</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCPRT002</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Support the rights and safety of children and young people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCPRT008</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide supervision in a secure system</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCSET001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Work with forced migrants</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCSET002</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Undertake bicultural work with forced migrants in Australia</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCSOH001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Work with people experiencing or at risk of homelessness</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCYTH001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Engage respectfully with young people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCYTH004</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Respond to critical situations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCYTH005</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop and implement procedures to enable young people to address their needs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCYTH010</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide services for young people appropriate to their needs and circumstances</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CHCYTH012</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage service response to young people in crisis</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>HLTAID006</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide advanced first aid</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBATSIW515</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Secure funding</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBFIM501</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage budgets and financial plans</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBHRM506</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage recruitment selection and induction processes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBHRM513</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage workforce planning</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBINN601</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Lead and manage organisational change</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBMGT404</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Lead and facilitate off-site staff</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBMGT502</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage people performance</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBMGT516</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Facilitate continuous improvement</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBMGT605</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide leadership across the organisation</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBPMG511</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage project scope</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBPMG512</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage project time</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBPMG513</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage project quality</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBPMG514</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage project cost</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBPMG515</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage project human resources</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBPMG516</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage project information and communication</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBPMG519</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage project stakeholder engagement</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBPMG522</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Undertake project work</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBPUB504</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Develop and implement crisis management plans</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBRSK501</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage risk</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBWOR403</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Manage stress in the workplace</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>BSBWOR502</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Lead and manage team effectiveness</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>CPPSEC3013A</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Control person using empty hand techniques</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>PSPGOV506A</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Support workplace coaching and mentoring</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"216\">\r\n<p>TAEDEL502A</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide advanced facilitation practice</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '70.jpg', 'CHC52015.pdf', 1, '2021-04-27 02:50:59', '2021-06-02 03:18:11'),
(95, 1, 6, 1, 26, 'CPC50210', 'Diploma of Building and Construction (Building)', '<h2>Description</h2>\r\n<p>&nbsp;</p>\r\n<p>This qualification is designed to meet the needs of builders, including selecting contractors, overseeing the work and its quality, and liaising with clients.</p>\r\n<p>The builder may also be the appropriately licensed person with responsibility under the relevant building licensing authority in the State or Territory. Builder licensing varies across States and Territories and additional requirements to attainment of this qualification may be required.</p>\r\n<p>Occupational title may include:</p>\r\n<ul>\r\n<li>Builder.</li>\r\n</ul>\r\n<p>The qualification has core unit of competency requirements that cover common skills for the construction industry.</p>\r\n<p>The construction industry strongly affirms that training and assessment leading to recognition of skills must be undertaken in a real or very closely simulated workplace environment and this qualification requires all included units of competency to be delivered in this context.</p>\r\n<p>Completion of the general induction training program specified by the National Code of Practice for Induction Training for Construction Work (ASCC 2007) is required before entering a construction work site. Achievement of unit CPCCOHS1001A covers this requirement.</p>\r\n<p>Additional units of competency may be required to meet builder registration requirements in various States and Territories.</p>\r\n<p>&nbsp;</p>\r\n<h2>Pathways Information</h2>\r\n<p>Not Applicable</p>\r\n<h2>Licensing/Regulatory Information</h2>\r\n<p>Occupational licenses are required nationally.</p>\r\n<p>Refer to Description</p>\r\n<p>&nbsp;</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Not Applicable</p>\r\n<h2>Employability Skills Summary</h2>\r\n<p>&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"200\">\r\n<p>Employability skill&nbsp;</p>\r\n</td>\r\n<td width=\"805\">\r\n<p>Industry/enterprise requirements for this qualification include:&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"200\">\r\n<p>Communication&nbsp;</p>\r\n</td>\r\n<td width=\"805\">\r\n<ul>\r\n<li>Analyses, evaluates and interprets a range of complex and technical documents, including relevant regulatory, legislative, licensing requirements, codes and standards, plans, drawings and specifications, contracts, reports, reference materials, building approvals, awards and workplace agreements</li>\r\n<li>Maintains and reports records and information</li>\r\n<li>Understands relevant definitions, terminology, symbols and language</li>\r\n<li>Communicates effectively with a range of relevant parties and provides expert testimony</li>\r\n<li>Establishes site communication procedures</li>\r\n<li>Prepares complex business documents, including project expenditure schedules and reports, such as technical and legal reports, drawings and project briefs</li>\r\n<li>Advises others regarding their obligations as well as company procedures</li>\r\n<li>Negotiates dispute resolution</li>\r\n<li>Sketches service layouts</li>\r\n<li>Implements feedback systems</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"200\">\r\n<p>Teamwork&nbsp;</p>\r\n</td>\r\n<td width=\"805\">\r\n<ul>\r\n<li>Demonstrates leadership within work teams and business units</li>\r\n<li>Collaboratively and effectively develops and implements operational plans</li>\r\n<li>Supervises work processes and systems, and delegates to others as required</li>\r\n<li>Works with others to overcome problems and achieve outcomes</li>\r\n<li>Establishes and maintains effective working relationships</li>\r\n<li>Seeks advice from senior management as required</li>\r\n<li>Works collaboratively with relevant stakeholders</li>\r\n<li>Relates to people from diverse social, cultural and ethnic backgrounds and with varying physical and mental abilities</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"200\">\r\n<p>Problem solving&nbsp;</p>\r\n</td>\r\n<td width=\"805\">\r\n<ul>\r\n<li>Analyses construction, environmental management, and energy conservation problems and applies appropriate and compliant remedial solutions</li>\r\n<li>Assesses structural integrity of medium rise buildings</li>\r\n<li>Ensures processes that identify faults and required remedial action</li>\r\n<li>Develops strategies to address project delays</li>\r\n<li>Performs various complex calculations relating to cost-benefit analysis, rise and fall amounts, pessimistic overdraft requirements, statistical analysis, costs, set out of construction work, structural analysis and service installations</li>\r\n<li>Analyses reasons for cost variations and takes remedial action</li>\r\n<li>Establishes and implements dispute resolution procedures</li>\r\n<li>Maintains site safety and manages risks</li>\r\n<li>Provides advice on dispute resolution</li>\r\n<li>Uses and analyses data in decision making</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"200\">\r\n<p>Initiative and enterprise&nbsp;</p>\r\n</td>\r\n<td width=\"805\">\r\n<ul>\r\n<li>Develops and initiates strategies to use resources effectively</li>\r\n<li>Ensures effective systems\' development</li>\r\n<li>Implements effective project quality management and continuous improvement processes</li>\r\n<li>Recommends improvements to environmental management and energy conservation plans</li>\r\n<li>Develops strategies that maximise resource effectiveness</li>\r\n<li>Develops and reviews workplace sustainability policy</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"200\">\r\n<p>Planning and organising&nbsp;</p>\r\n</td>\r\n<td width=\"805\">\r\n<ul>\r\n<li>Supervises planning processes and organisation of on-site building or construction work projects, including instituting procedures and systems</li>\r\n<li>Develops sound and safe practices in relation to structural procedures on site</li>\r\n<li>Coordinates and manages construction and demolition processes</li>\r\n<li>Monitors building or construction costing systems</li>\r\n<li>Manages preparation of project expenditure schedules</li>\r\n<li>Supervises materials\' procurement systems</li>\r\n<li>Manages selection, engagement and performance of building and construction contractors</li>\r\n<li>Administers legal obligations of building or construction contracts</li>\r\n<li>Establishes construction work policies, practices and procedures</li>\r\n<li>Prepares and implements environmental management and energy conservation plans, including workplace sustainability policy</li>\r\n<li>Advises and coordinates design process and obtains planning approval</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"200\">\r\n<p>Self management&nbsp;</p>\r\n</td>\r\n<td width=\"805\">\r\n<ul>\r\n<li>Manages own performance to ensure required levels of service standards, work quality and professional competence</li>\r\n<li>Manages work priorities and professional development</li>\r\n<li>Uses feedback to improve own performance</li>\r\n<li>Takes responsibility as required by the work role</li>\r\n<li>Uses discretion and judgement when required in complex environments</li>\r\n<li>Deals with contingencies</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"200\">\r\n<p>Learning&nbsp;</p>\r\n</td>\r\n<td width=\"805\">\r\n<ul>\r\n<li>Is open to new ideas and techniques</li>\r\n<li>Seeks feedback on personal performance</li>\r\n<li>Uses information effectively to improve work performance</li>\r\n<li>Learns from colleagues as part of effective teamwork</li>\r\n<li>Manages induction and pre-engagement training processes</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"200\">\r\n<p>Technology&nbsp;</p>\r\n</td>\r\n<td width=\"805\">\r\n<ul>\r\n<li>Operates office equipment</li>\r\n<li>Uses computer equipment and relevant software</li>\r\n<li>Understands building construction materials and technologies</li>\r\n<li>Understands construction equipment and its use</li>\r\n<li>Operates and tests levelling equipment</li>\r\n<li>Uses technology to improve efficiency and effectiveness of managing work</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h2>Packaging Rules</h2>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>To achieve this qualification, the candidate must demonstrate competency in:</p>\r\n<ul>\r\n<li>18 units of competency:</li>\r\n</ul>\r\n<ul>\r\n<li>13 core units</li>\r\n<li>5 elective units.</li>\r\n</ul>\r\n<p>The elective units must be selected as follows:</p>\r\n<ul>\r\n<li>a minimum of 3 elective units must be from Group A units below</li>\r\n<li>a maximum of 2 further elective units may be from Group B units below</li>\r\n<li>1 elective unit may be from Diploma level in from CPC08 or another endorsed Training Package, provided that the industry context of the qualification is maintained</li>\r\n<li>2 elective units may be from any Certificate IV in CPC08</li>\r\n<li>1 elective unit may be from any Advanced Diploma in CPC08.</li>\r\n</ul>\r\n<p>Some units in this qualification may have prerequisite requirements, which must be met when packaging the qualification. Users are referred to the list of CPC08 units with prerequisite unit requirements available in this Training Package for this purpose.</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Core units&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBOHS504B</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Apply principles of OHS risk management</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBPMG505A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage project quality</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBPMG508A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage project risk</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Apply building codes and standards to the construction process for low rise building projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4003A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Select and prepare a construction contract</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4004A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Identify and produce estimated costs for building and construction projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4010B</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Apply structural principles to residential low rise constructions</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4013A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Prepare and evaluate tender documentation</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5001B</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Apply building codes and standards to the construction process for medium rise building projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5002A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Monitor costing systems on medium rise building and construction projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5003A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Supervise the planning of on-site medium rise building or construction work</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5010B</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage construction work</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5018A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Apply structural principles to the construction of medium rise buildings</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>&nbsp;</p>\r\n<p>Elective units &ndash; Group A&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5004A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Supervise and apply quality standards to the selection of building and construction materials</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5005A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Select and manage building and construction contractors</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5006B</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Apply site surveys and set-out procedures to medium rise building projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5007B</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Administer the legal obligations of a building or construction contractor</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5009A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Identify services layout and connection methods to medium rise construction projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5011A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage environmental management practices and processes in building and construction</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5012A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage the application and monitoring of energy conservation and management practices and processes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5013A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Develop professional technical and legal reports on building and construction projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCSUS5001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Develop workplace policies and procedures for sustainability</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCSUS5002A</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>Develop action plans to retrofit existing buildings for energy efficiency</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCSUS5003A</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>Manage energy efficient building methods and strategies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Elective units &ndash; Group B&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBCUS501</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage quality customer service</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBFIM501</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage budgets and financial plans</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBHRM509</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage rehabilitation or return to work programs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBINN502</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Build and sustain an innovative work environment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBITA401</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Design databases</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBITU402</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Develop and use complex spreadsheets</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBITU404</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Produce complex desktop published documents</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBLED502</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage programs that promote personal effectiveness</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBMGT502</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage people performance</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBMGT517</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage operational plan</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBRSK501</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage risk</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBSLS502</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Lead and manage a sales team</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBWOR501</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage personal work priorities and professional development</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>BSBWOR502</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Lead team effectiveness</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4005A</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>Produce labour and material schedules for ordering</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4006B</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>Select, procure and store construction materials for low rise projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4009B</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>Apply legal requirements to building and construction projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4011B</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>Apply structural principles to commercial low rise constructions</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4012B</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>Read and interpret plans and specifications</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4014A</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>Prepare simple building sketches and drawings</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4018A</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>Apply site surveys and set-out procedures to building and construction projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC4024A</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>Resolve business disputes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5004A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Supervise and apply quality standards to the selection of building and construction materials</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5005A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Select and manage building and construction contractors</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5006B</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Apply site surveys and set-out procedures to medium rise building projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5007B</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Administer the legal obligations of a building or construction contractor</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5009A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Identify services layout and connection methods to medium rise construction projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5011A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage environmental management practices and processes in building and construction</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5012A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Manage the application and monitoring of energy conservation and management practices and processes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5013A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Develop professional technical and legal reports on building and construction projects</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCBC5014A</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>Conduct asbestos assessment associated with removal</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPCCWHS1001</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>Prepare to work safely in the construction industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>CPPDSM5022A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Implement asset management plan</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '21.jpg', 'CPC50210.pdf', 1, '2021-04-27 02:51:39', '2021-06-02 03:28:43'),
(96, 1, 10, 1, 26, 'CPC80215', 'Graduate Diploma of Building Surveying', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of senior building surveyors and principals of private building surveying practices who:</p>\r\n<ul>\r\n<li>manage building surveying processes and teams</li>\r\n<li>advise on a range of compliance requirements for residential, commercial and industrial building projects</li>\r\n<li>work with a range of specialist consultants to develop workable solutions to identified areas of non-compliance in building developments.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Senior building surveyors and principals work in a highly regulated environment and must carry out their tasks ethically and according to legislative and regulatory requirements.</p>\r\n<p>&nbsp;</p>\r\n<p>Licensing, legislative, regulatory or certification requirements apply to building surveying in some States. Relevant state and territory regulatory authorities should be consulted to confirm those requirements.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>There are no entry requirements for this qualification.</p>\r\n<h2>Packaging Rules</h2>\r\n<p>To achieve this qualification, competency must be demonstrated in:</p>\r\n<ul>\r\n<li>8 units of competency:</li>\r\n</ul>\r\n<ul>\r\n<li>6 core units</li>\r\n<li>2 elective units.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>The elective units must ensure the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome and are to be chosen as follows:</p>\r\n<ul>\r\n<li>both units may be chosen from the elective units listed below</li>\r\n<li>up to 1 unit may be chosen from other Graduate Diploma qualifications in CPC or another current Training Package or accredited course, provided they do not duplicate the outcome of another unit chosen for the qualification.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Core units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"240\">\r\n<p>CPCCBS8001</p>\r\n</td>\r\n<td width=\"756\">\r\n<p>Manage building surveying risks and ensure compliance with ethical and professional standards</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"240\">\r\n<p>CPCCBS8004</p>\r\n</td>\r\n<td width=\"756\">\r\n<p>Advise on compliance of building design documentation</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"240\">\r\n<p>CPCCBS8006</p>\r\n</td>\r\n<td width=\"756\">\r\n<p>Manage building approval processes for all building types</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"240\">\r\n<p>CPCCBS8007</p>\r\n</td>\r\n<td width=\"756\">\r\n<p>Monitor building work and advise on compliance issues</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"240\">\r\n<p>CPCCBS8008</p>\r\n</td>\r\n<td width=\"756\">\r\n<p>Conduct and manage the completion of building inspections and audits</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"240\">\r\n<p>CPCCBS8011</p>\r\n</td>\r\n<td width=\"756\">\r\n<p>Assess and advise on performance-based solutions for all types of buildings</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>&nbsp;</p>\r\n<p>Elective units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"240\">\r\n<p>CPCCBS8002</p>\r\n</td>\r\n<td width=\"756\">\r\n<p>Manage information on construction methods, materials and services for a building surveying team</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"240\">\r\n<p>CPCCBS8003</p>\r\n</td>\r\n<td width=\"756\">\r\n<p>Manage information on compliance requirements for a building surveying team</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"240\">\r\n<p>CPCCBS8005</p>\r\n</td>\r\n<td width=\"756\">\r\n<p>Manage planning approval processes for all building types</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"240\">\r\n<p>CPCCBS8009</p>\r\n</td>\r\n<td width=\"756\">\r\n<p>Lead a building surveying team</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"240\">\r\n<p>CPCCBS8010</p>\r\n</td>\r\n<td width=\"756\">\r\n<p>Liaise and coordinate with head contractors on building projects</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '103.jpg', 'CPC80215.pdf', 1, '2021-04-27 02:52:52', '2021-06-02 03:29:35');
INSERT INTO `courses` (`id`, `action_user`, `course_industries_id`, `qualification_id`, `course_categories_id`, `course_code`, `course_name`, `course_desc`, `rto`, `thumbnail`, `checklist`, `isPublished`, `created_at`, `updated_at`) VALUES
(97, 1, 7, 1, 26, 'CPP50511', 'Diploma of Property Services (Asset and facility management)', '<h2>Description</h2>\r\n<p>Not Applicable</p>\r\n<h2>Pathways Information</h2>\r\n<p>Not Applicable</p>\r\n<h2>Licensing/Regulatory Information</h2>\r\n<p>Not Applicable</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Not Applicable</p>\r\n<h2>Employability Skills Summary</h2>\r\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"1\" width=\"936\">\r\n<tbody>\r\n<tr>\r\n<td width=\"388\">\r\n<p>Employability Skill&nbsp;</p>\r\n</td>\r\n<td width=\"547\">\r\n<p>Industry&nbsp;/enterprise requirements for this qualification include&nbsp;:</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"388\">\r\n<p>Communication&nbsp;</p>\r\n</td>\r\n<td width=\"547\">\r\n<ul>\r\n<li>apply literacy skills to access and use workplace information and report on customer service strategies</li>\r\n<li>apply numeracy skills to interpret statistical information</li>\r\n<li>apply communication skills to present marketing and sales information to clients, and interpret written and oral information</li>\r\n<li>communicate to all those involved in service delivery within appropriate timeframes</li>\r\n<li>demonstrate report writing skills to create a project brief, terms of reference or project charter and prepare written reports on project\'s progress</li>\r\n<li>prepare and establish documentation and checklists associated with project plan implementation in established formats and distribute them to relevant people</li>\r\n<li>prepare draft tender documentation which accurately reflects project requirements and complies with specific tender criteria and conditions</li>\r\n<li>select appropriate methods and adapt communication styles when communicating with clients</li>\r\n<li>use language skills to allow for adequate communication with relevant personnel</li>\r\n<li>use effective communication strategies to encourage regular and accurate communication flow and feedback</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"388\">\r\n<p>Teamwork&nbsp;</p>\r\n</td>\r\n<td width=\"547\">\r\n<ul>\r\n<li>inform team of changes in policies and procedures that affect their relations with customers</li>\r\n<li>motivate team to achieve high standard of service to customers</li>\r\n<li>use interpersonal skills to relate to people from a range of social, cultural and ethnic backgrounds and varying physical and mental abilities</li>\r\n<li>use leadership skills to gain trust and confidence of clients and colleagues</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"388\">\r\n<p>Problem solving&nbsp;</p>\r\n</td>\r\n<td width=\"547\">\r\n<ul>\r\n<li>apply problem solving skills to develop contingency plans and select alternative marketing and sales options and to negotiate strategies with clients</li>\r\n<li>apply problem solving skills to analyse entire work environment in area of responsibility in order to identify hazards, assess risks and judge when intervention to control risks is necessary</li>\r\n<li>modify specific aspects of products, services and their delivery to meet changing customer service requirements</li>\r\n<li>use problem solving skills to deal with complex and non-routine difficulties</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"388\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width=\"547\">\r\n<ul>\r\n<li>use problem solving skills to identify potential barriers to project outcomes, analyse project risks and establish contingencies</li>\r\n<li>use evaluation skills to identify potential or existing risks and hazards in the workplace, identify inadequacies in risk control measures and determine OHS training requirements of the work group</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"388\">\r\n<p>Initiative and enterprise&nbsp;</p>\r\n</td>\r\n<td width=\"547\">\r\n<ul>\r\n<li>analyse and interpret information to identify and assess customer needs, expectations and satisfaction levels</li>\r\n<li>analyse and evaluate information on how organisation compares with competition and best practice</li>\r\n<li>identify and analyse project brief according to organisational requirements to determine project requirements</li>\r\n<li>identify and use systematic review processes and established evaluation methods to assess project processes and outcomes</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"388\">\r\n<p>Planning and organising&nbsp;</p>\r\n</td>\r\n<td width=\"547\">\r\n<ul>\r\n<li>collect and analyse current market and sales information</li>\r\n<li>develop plans to meet customer needs and deliver improved customer service</li>\r\n<li>identify marketing and sales activities and required resources and incorporate into a marketing and sales strategy</li>\r\n<li>identify customer service problems and make adjustments to ensure continued service quality</li>\r\n<li>identify targets and milestones and link to achievement of outcomes according to project plan</li>\r\n<li>monitor and report arrangements for project activities in line with client requirements</li>\r\n<li>source information through both formal and informal channels according to organisational requirements</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"388\">\r\n<p>Self-management&nbsp;</p>\r\n</td>\r\n<td width=\"547\">\r\n<ul>\r\n<li>evaluate own work relationships systematically in order to identify new networking opportunities</li>\r\n<li>develop strategies to obtain ongoing feedback to maintain and improve client relationships</li>\r\n<li>identify when expert advice is needed, obtain advice and act on it promptly</li>\r\n<li>identify personal limitations in assessing tender requirements and seek assistance as required from relevant people</li>\r\n<li>participate and influence business networks</li>\r\n<li>use time management skills to logically sequence project activities</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"388\">\r\n<p>Learning&nbsp;</p>\r\n</td>\r\n<td width=\"547\">\r\n<ul>\r\n<li>apply knowledge of organisation\'s practices, ethical standards and legislative requirements associated with analysing a population or market segment</li>\r\n<li>coach and mentor to provide support to colleagues</li>\r\n<li>use knowledge of workforce characteristics and how they impact on the design and maintenance of OHS</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"388\">\r\n<p>Technology&nbsp;</p>\r\n</td>\r\n<td width=\"547\">\r\n<ul>\r\n<li>apply computing skills to access the internet and web pages, prepare and complete online forms, lodge electronic documents and search online databases</li>\r\n<li>use business equipment and technology to access, analyse and organise information according to organisational requirements</li>\r\n<li>use technology skills to maintain databases and source information</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Due to the high proportion of electives required by this qualification, the industry/enterprise requirements described above for each Employability Skill are representative of the property industry in general and may not reflect specific job roles. Learning and assessment strategies for this qualification should be based on the requirements of the units of competency for this qualification.</p>\r\n<p>This table is a summary of Employability Skills that are typical of this qualification and should not be interpreted as definitive.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h2>Packaging Rules</h2>\r\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"1\" width=\"929\">\r\n<tbody>\r\n<tr>\r\n<td colspan=\"2\" width=\"929\">\r\n<p>To achieve this qualification, the candidate must demonstrate competency in:</p>\r\n<ul>\r\n<li>16 units of competency:</li>\r\n</ul>\r\n<ul>\r\n<li>8 Group A units</li>\r\n<li>8 Group B units.</li>\r\n</ul>\r\n<p>The Group A units are chosen as follows:</p>\r\n<ul>\r\n<li>8 units may be chosen from Group A</li>\r\n<li>2 of the units may be chosen from:</li>\r\n</ul>\r\n<ul>\r\n<li>Certificate IV in Property Services (Operations) or Advanced Diploma of Property Services (Asset and Facility Management)</li>\r\n<li>any Diploma qualification in CPP07 or another current Training Package.</li>\r\n</ul>\r\n<p>The Group B units are chosen as follows:</p>\r\n<ul>\r\n<li>8 units may be chosen from Group B</li>\r\n<li>2 of the units may be chosen from:</li>\r\n</ul>\r\n<ul>\r\n<li>Certificate IV in Property Services (Operations) or Advanced Diploma of Property Services (Asset and Facility Management)</li>\r\n<li>any Diploma qualification in CPP07 or another current Training Package or state accredited course, provided the integrity of the AQF alignment is ensured, and they contribute to a valid, industry-supported vocational outcome.</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"929\">\r\n<p>&nbsp;</p>\r\n<p>Group A Common units&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>BSBFIM501</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Manage budgets and financial plans</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>BSBHRM405</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Support the recruitment, selection and induction of staff</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>BSBMGT502</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Manage people performance</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>BSBMGT517</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Manage operational plan</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>BSBSUS501</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Develop workplace policy and procedures for sustainability</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPCSUS5002A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Develop action plans to retrofit existing buildings for energy efficiency</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPCSUS5003A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Manage energy efficient building methods and strategies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPCMN5001A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Plan for a sustainable business</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5006A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Coordinate customer service activities in the property industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5009A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Coordinate risk management system in the property industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5010A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Determine needs of customer populations in the property industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5014A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Develop property marketing and sales strategy</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5018A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Ensure a safe workplace in the property industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5029A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Manage client relationships and networks in the property industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5030A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Manage projects in the property industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5036A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Prepare tender documentation in the property industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"929\">\r\n<p>&nbsp;</p>\r\n<p>Group B Specialist units&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"929\">\r\n<p>Development&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5004A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Assess viability of regeneration options in the property industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5005A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Contribute to a detailed property feasibility study</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5008A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Coordinate fit-out of premises for user occupation</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5011A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Determine space utilisation</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5017A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Dispose of property</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5019A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Identify and secure a property opportunity</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5026A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Manage a consultant property project team</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"929\">\r\n<p>&nbsp;</p>\r\n<p>Management&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5002A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Advise on property investment strategy</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5013A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Develop a tenancy mix strategy</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5016A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Develop strata/community management agreement</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5021A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Implement asset maintenance strategy</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5022A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Implement asset management plan</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5025A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Maintain public relations in the property industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"929\">\r\n<p>&nbsp;</p>\r\n<p>Facilities&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5001A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Advise on use and design of facilities</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5007A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Coordinate construction or renovation of facilities</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5023A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Implement facilities management plan</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5024A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Implement facilities procurement systems</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5027A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Provide facilities and amenities for property users</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"282\">\r\n<p>CPPDSM5034A</p>\r\n</td>\r\n<td width=\"647\">\r\n<p>Monitor performance of property or facility portfolio</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '71.jpg', 'CPP50511.pdf', 1, '2021-04-27 02:53:37', '2021-06-02 03:32:18'),
(98, 1, 10, 1, 26, 'FNS50217', 'Diploma of Accounting', NULL, NULL, '104.jpg', 'FNS50217.pdf', 1, '2021-04-27 02:54:10', '2021-04-27 02:54:10'),
(99, 1, 10, 1, 26, 'FNS50615', 'Diploma of Financial Planning', NULL, NULL, '105.jpg', 'FNS50615.pdf', 1, '2021-04-27 02:54:55', '2021-04-27 02:54:55'),
